}

class SCCList {
    private SCC first, last;

    void addSCC(Stack<Integer> stack) {
        SCC newSCC = new SCC(stack);
        if (first == null)
            first = last = newSCC;
        else {
            last.setNext(newSCC);
            last = newSCC;
        }
    }

    SCC getFirst() {
        return first;
    }
}

