class Lista_CFC {
    private CFC primeiro, ultimo;

    void add2Lista(Stack pilha) {
        CFC compfc = new CFC(pilha);
        if (primeiro == null) {
            primeiro = ultimo = compfc;
        } else {
            ultimo.setNext(compfc);
            ultimo = compfc;
        }
    }

    CFC getPrimeiro() {
        return primeiro;
    }
}

class CFC {
    private Stack componente;
    private CFC next;

    CFC(Stack comp) {
        componente = comp;
    }

    void setNext(CFC no) {
        next = no;
    }

    CFC getNext() {
        return next;
    }

    Stack getComponente() {
        return componente;
    }
}

class Stack {
    private int elems = 0;
    private Node first = null;

    boolean isEmpty() {
        return first == null;
    }

    void push(int x) {
        Node no = new Node(x, first);
        first = no;
        elems++;
    }

    int pop() {
        if (isEmpty()) return -1; // Error handling for empty stack
        int x = first.getValor();
        first = first.getNext();
        elems--;
        return x;
    }

    boolean elemInStack(int x) {
        for (Node i = first; i != null; i = i.getNext()) if (i.getValor() == x) return true;
        return false;
    }

    int elemsStack() {
        return elems;
    }

    Stack getTill(int v) {
        Stack s = new Stack();
        int i;
        do {
            i = pop();
            s.push(i);
        } while (i != v && !isEmpty()); // Ensure pop until find v or stack is empty
        return s;
    }

    int[] getElements() {
        int[] elements = new int[elems];
        int j = 0;
        for (Node i = first; i != null; i = i.getNext()) elements[j++] = i.getValor();
        return elements;
    }
}

class Node {
    private int valor;
    private Node next;

    Node(int x, Node nextNode) {
        valor = x;
        next = nextNode;
    }

    int getValor() {
        return valor;
    }

    Node getNext() {
        return next;
    }
}

