                Iterator<Integer> it = groups[j].iterator();
                while (it.hasNext()) {
                    count++;
                    it.next();
                }
                if (count >= 4)
                    nGroups += 1;
                else
                    nElemOut += count;
                count = 0;
            }
            System.out.printf("%d %d\n", nGroups, nElemOut);
        }
    }
}

