import java.io.*;
import java.util.*;

class GraphEdge implements Comparable<GraphEdge> {
    double weight;
    int fromNode;
    int toNode;

    GraphEdge(double weight, int fromNode, int toNode) {
        this.weight = weight;
        this.fromNode = fromNode;
        this.toNode = toNode;
    }

    @Override
    public int compareTo(GraphEdge other) {
        return Double.compare(this.weight, other.weight);
    }
}

class UnionFind {
    private int[] parent;
    private int[] rank;

    UnionFind(int size) {
        parent = new int[size];
        rank = new int[size];
        for (int i = 0; i < size; i++) {
            parent[i] = i;
            rank[i] = 0;
        }
    }

    int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }

    boolean union(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);
        if (rootX != rootY) {
            if (rank[rootX] > rank[rootY]) {
                parent[rootY] = rootX;
            } else {
                parent[rootX] = rootY;
                if (rank[rootX] == rank[rootY]) rank[rootY]++;
            }
            return true;
        }
        return false;
    }
}

class MinimumSpanningTreeCalculator {
    private static List<GraphEdge> edgeList;
    private static int numberOfNodes;

    private static double calculateMinimumSpanningTree() {
        double totalCost = 0;
        UnionFind unionFind = new UnionFind(numberOfNodes);
        Collections.sort(edgeList);

        for (GraphEdge edge : edgeList) {
            if (unionFind.union(edge.fromNode, edge.toNode)) {
                totalCost += edge.weight;
            }
        }
        return totalCost;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        numberOfNodes = scanner.nextInt();
        double[] xCoordinates = new double[numberOfNodes];
        double[] yCoordinates = new double[numberOfNodes];
        edgeList = new ArrayList<>();

        for (int i = 0; i < numberOfNodes; ++i) {
            xCoordinates[i] = scanner.nextDouble();
            yCoordinates[i] = scanner.nextDouble();
        }

        for (int i = 0; i < numberOfNodes - 1; ++i) {
            for (int j = i + 1; j < numberOfNodes; ++j) {
                double dx = xCoordinates[i] - xCoordinates[j];
                double dy = yCoordinates[i] - yCoordinates[j];
                double distance = Math.sqrt(dx * dx + dy * dy);
                edgeList.add(new GraphEdge(distance, i, j));
            }
        }

        System.out.printf("%.2f%n", calculateMinimumSpanningTree());
    }
}

