class KruskalAlgorithm {
    private static List<Edge> edgeList;
    private static int vertexCount;
    private static int[] parent;
    private static int[] rank;

    private static void initializeUnionFind(int size) {
        parent = new int[size];
        rank = new int[size];
        for (int i = 0; i < size; i++) {
            parent[i] = i;
            rank[i] = 0;
        }
    }

    private static int find(int i) {
        if (i != parent[i]) {
            parent[i] = find(parent[i]);
        }
        return parent[i];
    }

    private static boolean isSameComponent(int i, int j) {
        return find(i) == find(j);
    }

    private static void union(int i, int j) {
        int rootI = find(i);
        int rootJ = find(j);
        if (rank[rootI] > rank[rootJ]) {
            parent[rootJ] = rootI;
        } else {
            parent[rootI] = rootJ;
            if (rank[rootI] == rank[rootJ]) {
                rank[rootJ]++;
            }
        }
    }

    private static double calculateMST() {
        double totalCost = 0;
        initializeUnionFind(vertexCount);
        Collections.sort(edgeList);
        for (Edge edge : edgeList) {
            if (!isSameComponent(edge.source, edge.destination)) {
                union(edge.source, edge.destination);
                totalCost += edge.weight;
            }
        }
        return totalCost;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        vertexCount = scanner.nextInt();
        double[] xCoordinates = new double[vertexCount];
        double[] yCoordinates = new double[vertexCount];
        edgeList = new ArrayList<>();

        for (int i = 0; i < vertexCount; ++i) {
            xCoordinates[i] = scanner.nextDouble();
            yCoordinates[i] = scanner.nextDouble();
        }

        for (int i = 0; i < vertexCount - 1; ++i) {
            for (int j = i + 1; j < vertexCount; ++j) {
                double distance = computeDistance(xCoordinates[i], xCoordinates[j], yCoordinates[i], yCoordinates[j]);
                edgeList.add(new Edge(distance, i, j));
                edgeList.add(new Edge(distance, j, i));
            }
        }

        System.out.println(String.format("%.2f", calculateMST()));
    }

    private static double computeDistance(double x1, double x2, double y1, double y2) {
        double dx = x1 - x2;
        double dy = y1 - y2;
        return Math.sqrt(dx * dx + dy * dy);
    }
}

