class Edge implements Comparable<Edge> {
    double weight;
    int source;
    int destination;

    Edge(double weight, int source, int destination) {
        this.weight = weight;
        this.source = source;
        this.destination = destination;
    }

    @Override
    public int compareTo(Edge other) {
        return Double.compare(this.weight, other.weight);
    }
}

class GraphAlgorithms {
    static List<Edge> edges;
    static int verticesCount;
    static int[] parent;
    static int[] treeRank;

    static void initializeUnionFind(int size) {
        parent = new int[size];
        treeRank = new int[size];
        for (int i = 0; i < size; i++) {
            parent[i] = i;
            treeRank[i] = 0;
        }
    }

    static int find(int i) {
        if (i != parent[i]) parent[i] = find(parent[i]);
        return parent[i];
    }

    static boolean isConnected(int i, int j) {
        return find(i) == find(j);
    }

    static void merge(int i, int j) {
        int rootI = find(i);
        int rootJ = find(j);
        if (treeRank[rootI] > treeRank[rootJ])
            parent[rootJ] = rootI;
        else {
            parent[rootI] = rootJ;
            if (treeRank[rootI] == treeRank[rootJ])
                treeRank[rootJ]++;
        }
    }

    static double minimumSpanningTreeCost() {
        double mstCost = 0;
        initializeUnionFind(verticesCount);
        Collections.sort(edges);
        for (Edge edge : edges) {
            if (!isConnected(edge.source, edge.destination)) {
                merge(edge.source, edge.destination);
                mstCost += edge.weight;
            }
        }
        return mstCost;
    }

    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        verticesCount = input.nextInt();
        double[] xPos = new double[verticesCount];
        double[] yPos = new double[verticesCount];
        edges = new ArrayList<>();

        for (int i = 0; i < verticesCount; ++i) {
            xPos[i] = input.nextDouble();
            yPos[i] = input.nextDouble();
        }

        for (int i = 0; i < verticesCount - 1; ++i) {
            for (int j = i + 1; j < verticesCount; ++j) {
                double distanceX = xPos[i] - xPos[j];
                double distanceY = yPos[i] - yPos[j];
                double distance = Math.sqrt(distanceX * distanceX + distanceY * distanceY);
                edges.add(new Edge(distance, i, j));
                edges.add(new Edge(distance, j, i));
            }
        }

        System.out.printf("%.2f\n", minimumSpanningTreeCost());
    }
}

