import java.util.*;

class MinimumSpanningTreeCalculator {
    static double[][] adjacencyMatrix;
    static boolean[][] edgesVisited;
    static double[] minimumDistances;
    static int[] predecessors;
    static int vertexCount;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in).useLocale(Locale.US);

        initializeGraph(scanner);

        // Prim's algorithm to find the minimum spanning tree
        calculateMinimumSpanningTree(0);

        double totalWeight = calculateTotalWeight();
        System.out.printf(Locale.US, "%.2f\n", totalWeight);
    }

    private static void initializeGraph(Scanner scanner) {
        int n = vertexCount = scanner.nextInt();
        adjacencyMatrix = new double[n][n];
        edgesVisited = new boolean[n][n];
        minimumDistances = new double[n];
        predecessors = new int[n];
        double[][] coordinates = new double[n][2];

        for (int i = 0; i < n; i++) {
            coordinates[i][0] = scanner.nextDouble();
            coordinates[i][1] = scanner.nextDouble();
        }

        for (int i = 0; i < n; i++) {
            for (int j = i; j < n; j++) {
                if (i != j) {
                    adjacencyMatrix[j][i] = adjacencyMatrix[i][j] = calculateDistance(coordinates[i], coordinates[j]);
                }
            }
        }
    }

    private static double calculateDistance(double[] point1, double[] point2) {
        double xDiff = point1[0] - point2[0];
        double yDiff = point1[1] - point2[1];
        return Math.sqrt(xDiff * xDiff + yDiff * yDiff);
    }

    private static void calculateMinimumSpanningTree(int startVertex) {
        Arrays.fill(minimumDistances, Double.MAX_VALUE);
        boolean[] addedToTree = new boolean[vertexCount];
        minimumDistances[startVertex] = 0;
        predecessors[startVertex] = -1;

        for (int count = 0; count < vertexCount - 1; count++) {
            // Pick the minimum distance vertex from the set of vertices not yet
            // processed. u is always equal to startVertex in first iteration.
            int u = findMinimumDistanceVertex(addedToTree);
            addedToTree[u] = true;

            for (int v = 0; v < vertexCount; v++) {
                if (!addedToTree[v] && adjacencyMatrix[u][v] != 0 &&
                    adjacencyMatrix[u][v] < minimumDistances[v]) {
                    predecessors[v] = u;
                    minimumDistances[v] = adjacencyMatrix[u][v];
                }
            }
        }
    }

    private static int findMinimumDistanceVertex(boolean[] addedToTree) {
        double min = Double.MAX_VALUE;
        int minIndex = -1;

        for (int v = 0; v < vertexCount; v++) {
            if (!addedToTree[v] && minimumDistances[v] < min) {
                min = minimumDistances[v];
                minIndex = v;
            }
        }

        return minIndex;
    }

    private static double calculateTotalWeight() {
        double sum = 0;
        for (double distance : minimumDistances) {
            sum += distance;
        }
        return sum;
    }
}

