import java.util.*;

class FrecklesArt {

    private static int depthCounter = 0;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int numPoints = scanner.nextInt();
        Point[] points = new Point[numPoints];
        for (int i = 0; i < numPoints; i++) {
            points[i] = new Point(scanner.nextDouble(), scanner.nextDouble());
        }
        calculateMinimumDrawingDistance(points, numPoints);
    }

    private static void calculateMinimumDrawingDistance(Point[] points, int numPoints) {
        int components = numPoints;
        PriorityQueue<Connection> queue = new PriorityQueue<>();
        // Generate all possible links
        for (int i = 0; i < numPoints - 1; i++) {
            for (int j = i + 1; j < numPoints; j++) {
                queue.add(new Connection(i, j, calculateDistance(points[i], points[j])));
            }
        }
        double totalDistance = 0;
        while (!queue.isEmpty() && components > 1) {
            Connection closest = queue.poll();
            Point pointA = points[closest.pointA];
            Point pointB = points[closest.pointB];
            depthCounter = 0;
            Point rootA = findRoot(pointA);
            int depthA = depthCounter;
            depthCounter = 0;
            Point rootB = findRoot(pointB);
            int depthB = depthCounter;
            if (rootA != rootB) {
                union(rootA, rootB, depthA, depthB);
                components--;
                totalDistance += closest.distance;
            }
        }
        System.out.printf("%.2f%n", totalDistance);
    }

    private static double calculateDistance(Point a, Point b) {
        double deltaX = Math.abs(a.x - b.x);
        double deltaY = Math.abs(a.y - b.y);
        return Math.sqrt(deltaX * deltaX + deltaY * deltaY);
    }

    private static Point findRoot(Point point) {
        if (point.parent != point) {
            depthCounter++;
            point.parent = findRoot(point.parent);
        }
        return point.parent;
    }

    private static void union(Point rootA, Point rootB, int depthA, int depthB) {
        if (depthA > depthB) {
            rootB.parent = rootA;
        } else {
            rootA.parent = rootB;
        }
    }

    static class Point {
        Point parent;
        double x, y;

        Point(double x, double y) {
            this.x = x;
            this.y = y;
            this.parent = this; // Initially pointing to itself
        }
    }

    static class Connection implements Comparable<Connection> {
        int pointA, pointB;
        double distance;

        Connection(int a, int b, double distance) {
            this.pointA = a;
            this.pointB = b;
            this.distance = distance;
        }

        @Override
        public int compareTo(Connection other) {
            return Double.compare(this.distance, other.distance);
        }
    }
}

