class UnionFind {
    int n;
    int[] a;
    UnionFind(int n) {
        this.n = n;
        a = new int[n];
        for (int i = 0; i < n; i++)
            a[i] = i;
    }
    int FindSet(int i) {
        if (a[i] == i)
            return i;
        return a[i] = FindSet(a[i]);
    }
    void UnionSet(int l, int r) {
        a[FindSet(l)] = FindSet(r);
    }
}
