import java.util.*;

class Freckles {

    static double[][] coordinates;
    static double[][] matrix;
    static double[] minimumDistance;
    static boolean[] added;
    static int vertexCount;

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in).useLocale(Locale.US);
        vertexCount = in.nextInt();
        coordinates = new double[vertexCount][2];
        matrix = new double[vertexCount][vertexCount];
        minimumDistance = new double[vertexCount];
        added = new boolean[vertexCount];

        // Reading coordinates
        for (int i = 0; i < vertexCount; i++) {
            coordinates[i][0] = in.nextDouble();
            coordinates[i][1] = in.nextDouble();
        }

        // Preparing the weight matrix
        prepareWeightMatrix();
        // Calculate minimum spanning tree total weight using Prim's algorithm
        double totalWeight = primMST();

        System.out.printf(Locale.US, "%.2f\n", totalWeight);
    }

    private static void prepareWeightMatrix() {
        for (int i = 0; i < vertexCount; i++) {
            for (int j = i + 1; j < vertexCount; j++) {
                double distance = calculateDistance(coordinates[i][0], coordinates[i][1], coordinates[j][0], coordinates[j][1]);
                matrix[i][j] = matrix[j][i] = distance;
            }
        }
    }

    private static double calculateDistance(double x1, double y1, double x2, double y2) {
        return Math.sqrt(Math.pow(x1 - x2, 2) + Math.pow(y1 - y2, 2));
    }

    private static double primMST() {
        Arrays.fill(minimumDistance, Double.MAX_VALUE);
        minimumDistance[0] = 0; // Starting from the first vertex

        double totalWeight = 0;

        for (int i = 0; i < vertexCount; i++) {
            int nearestVertex = -1;
            // Find the vertex with the smallest distance to the tree
            for (int vertex = 0; vertex < vertexCount; vertex++) {
                if (!added[vertex] &&
                    (nearestVertex == -1 || minimumDistance[vertex] < minimumDistance[nearestVertex])) {
                    nearestVertex = vertex;
                }
            }

            // Include this nearest vertex to the set of added vertices
            added[nearestVertex] = true;
            totalWeight += minimumDistance[nearestVertex];

            // Update the minimum distances considering this new vertex
            for (int vertex = 0; vertex < vertexCount; vertex++) {
                double edgeWeight = matrix[nearestVertex][vertex];
                if (edgeWeight > 0 && !added[vertex] && edgeWeight < minimumDistance[vertex]) {
                    minimumDistance[vertex] = edgeWeight;
                }
            }
        }

        return totalWeight;
    }
}

