import java.io.*;
import java.util.*;

class Edge implements Comparable<Edge> {
    double weight;
    int source, destination;

    Edge(double weight, int source, int destination) {
        this.weight = weight;
        this.source = source;
        this.destination = destination;
    }

    @Override
    public int compareTo(Edge compareEdge) {
        if (this.weight < compareEdge.weight) return -1;
        else if (this.weight > compareEdge.weight) return 1;
        return 0;
    }
}

class DisjointSet {
    private int[] parent, rank;
    private int capacity;

    DisjointSet(int capacity) {
        this.capacity = capacity;
        this.parent = new int[capacity];
        this.rank = new int[capacity];
        for (int i = 0; i < capacity; ++i) {
            parent[i] = i;
            rank[i] = 0;
        }
    }

    int find(int i) {
        if (parent[i] != i)
            parent[i] = find(parent[i]);
        return parent[i];
    }

    void union(int x, int y) {
        int xRoot = find(x), yRoot = find(y);
        if (xRoot == yRoot) return;

        if (rank[xRoot] < rank[yRoot])
            parent[xRoot] = yRoot;
        else if (rank[xRoot] > rank[yRoot])
            parent[yRoot] = xRoot;
        else {
            parent[yRoot] = xRoot;
            rank[xRoot] = rank[xRoot] + 1;
        }
    }

    boolean isConnected(int x, int y) {
        return find(x) == find(y);
    }
}

class MSTKruskal {
    private static ArrayList<Edge> edgesList;
    private static int verticesCount;

    private static double calculateKruskalMST() {
        DisjointSet set = new DisjointSet(verticesCount);
        Collections.sort(edgesList);
        double cost = 0;

        for (Edge edge : edgesList) {
            if (!set.isConnected(edge.source, edge.destination)) {
                set.union(edge.source, edge.destination);
                cost += edge.weight;
            }
        }

        return cost;
    }

    private static void populateEdgesListWithWeights(double[] x, double[] y) {
        for (int i = 0; i < verticesCount - 1; ++i) {
            for (int j = i + 1; j < verticesCount; ++j) {
                double distance = Math.hypot(x[i] - x[j], y[i] - y[j]);
                edgesList.add(new Edge(distance, i, j));
            }
        }
    }

    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        verticesCount = input.nextInt();
        double[] xCoordinates = new double[verticesCount], yCoordinates = new double[verticesCount];

        for (int i = 0; i < verticesCount; ++i) {
            xCoordinates[i] = input.nextDouble();
            yCoordinates[i] = input.nextDouble();
        }

        edgesList = new ArrayList<>();
        populateEdgesListWithWeights(xCoordinates, yCoordinates);

        System.out.printf("%.2f\n", calculateKruskalMST());
    }
}

