    static int[] parent;
    static int[] depth;

    static void initializeDisjointSet(int size) {
        parent = new int[size];
        depth = new int[size];
        for (int i = 0; i < size; ++i) {
            parent[i] = i;
            depth[i] = 0;
        }
    }

    static int findRoot(int vertex) {
        if (vertex != parent[vertex])
            parent[vertex] = findRoot(parent[vertex]);
        return parent[vertex];
    }

    static boolean isConnected(int vertex1, int vertex2) {
        return findRoot(vertex1) == findRoot(vertex2);
    }

    static void unionVertices(int vertex1, int vertex2) {
        int root1 = findRoot(vertex1);
        int root2 = findRoot(vertex2);
        if (depth[root1] > depth[root2])
            parent[root2] = root1;
        else {
            parent[root1] = root2;
            if (depth[root1] == depth[root2])
                ++depth[root2];
        }
    }

    static double calculateMinimumSpanningTree() {
        double totalWeight = 0;
        initializeDisjointSet(vertexCount);
        Collections.sort(edgeList);
        for (Edge edge : edgeList) {
            if (!isConnected(edge.startVertex, edge.endVertex)) {
                unionVertices(edge.startVertex, edge.endVertex);
                totalWeight += edge.weight;
            }
        }
        return totalWeight;
    }
}

class MinimumSpanningTreeCalculator {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        Graph.vertexCount = scanner.nextInt();
        double[] xCoor = new double[Graph.vertexCount];
        double[] yCoor = new double[Graph.vertexCount];
        Graph.edgeList = new ArrayList<>();

        for (int i = 0; i < Graph.vertexCount; ++i) {
            xCoor[i] = scanner.nextDouble();
            yCoor[i] = scanner.nextDouble();
        }

        for (int i = 0; i < Graph.vertexCount - 1; ++i) {
            for (int j = i + 1; j < Graph.vertexCount; ++j) {
                double distance = calculateDistance(xCoor[i], xCoor[j], yCoor[i], yCoor[j]);
                Graph.edgeList.add(new Edge(distance, i, j));
                Graph.edgeList.add(new Edge(distance, j, i));
            }
        }

        System.out.printf("%.2f\n", Graph.calculateMinimumSpanningTree());
    }

    private static double calculateDistance(double x1, double x2, double y1, double y2) {
        return Math.sqrt(Math.pow(x1 - x2, 2) + Math.pow(y1 - y2, 2));
    }
}

import java.util.*;
class GNode {
    public ArrayList<Integer> filhos = new ArrayList<Integer>();
    public ArrayList<Integer> DFSresult = new ArrayList<Integer>();
    public int cor = 0;
}
class Search {
    public void DFS(GNode inicio, GNode[] listapontos, GNode origem) {
        inicio.cor = 1;
        for (int k = 0; k < inicio.filhos.size(); k++) {
            int temp = inicio.filhos.get(k);
            if (origem.DFSresult.contains(temp) == false) {
                origem.DFSresult.add(temp);
            }
            GNode filho = new GNode();
            if (listapontos[temp - 1].cor == 0) {
                filho = listapontos[temp - 1];
            }
            DFS(filho, listapontos, origem);
        }
    }
}
