class Edge implements Comparable<Edge> {
    private Node start;
    private Node end;
    private double distance;

    Edge(Node start, Node end) {
        this.start = start;
        this.end = end;
        this.distance = Math.sqrt(Math.pow(end.getX() - start.getX(), 2) + Math.pow(end.getY() - start.getY(), 2));
    }

    @Override
    public int compareTo(Edge other) {
        return Double.compare(this.distance, other.distance);
    }

    public double getDistance() {
        return distance;
    }

    public Node getStart() {
        return start;
    }

    public Node getEnd() {
        return end;
    }
}

class KruskalAlgorithm {
    private static LinkedList<NodeSet> nodeSets = new LinkedList<>();
    private static LinkedList<Edge> minimumSpanningTree = new LinkedList<>();
    private static LinkedList<Edge> edges = new LinkedList<>();

    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        Graph graph = new Graph(input.nextInt());
        for (int i = 0; i < graph.getNodes().length; i++) {
            graph.addNode(new Node(input.nextDouble(), input.nextDouble(), i));
        }

        initializeNodeSets(graph);
        createEdges(graph);

        Collections.sort(edges);
        formMinimumSpanningTree();
        printTotalDistance();
    }

    private static void initializeNodeSets(Graph graph) {
        for (Node node : graph.getNodes()) {
            nodeSets.add(new NodeSet(node, node.getIndex()));
        }
    }

    private static void createEdges(Graph graph) {
        for (int i = 0; i < graph.getNodeCount(); i++) {
            for (int j = i + 1; j < graph.getNodeCount(); j++) {
                edges.add(new Edge(graph.getNodes()[i], graph.getNodes()[j]));
            }
        }
    }

    private static void formMinimumSpanningTree() {
        for (Edge edge : edges) {
            int startIndex = findSetIndex(edge.getStart());
            int endIndex = findSetIndex(edge.getEnd());

            if (startIndex != endIndex) {
                minimumSpanningTree.add(edge);
                mergeSets(startIndex, endIndex);
            }
        }
    }

    private static int findSetIndex(Node node) {
        for (int i = 0; i < nodeSets.size(); i++) {
            for (Node setNode : nodeSets.get(i).getNodes()) {
                if (setNode.getX() == node.getX() && setNode.getY() == node.getY()) {
                    return i;
                }
            }
        }
        return -1;
    }

    private static void mergeSets(int startSetIndex, int endSetIndex) {
        NodeSet set1 = nodeSets.get(startSetIndex);
        NodeSet set2 = nodeSets.get(endSetIndex);
        set1.getNodes().addAll(set2.getNodes());
        nodeSets.remove(endSetIndex);
    }

    private static void printTotalDistance() {
        double totalDistance = 0.0;
        for (Edge edge : minimumSpanningTree) {
            totalDistance += edge.getDistance();
        }
        System.out.printf("%.2f\n", totalDistance);
    }
}

