class prob21 { static List<Node> nodelist; static int n; static int[] pset; static int[] rank;
    static void makeSet(int n1) { pset = new int[n1]; rank = new int[n1]; for (int i = 0; i < n1; i++) { pset[i] = i; rank[i] = 0; } }
    static int findSet(int i) { if (i != pset[i]) { pset[i] = findSet(pset[i]); } return pset[i]; }
    static boolean isSameSet(int i, int j) { return findSet(i) == findSet(j); }
    static void Union(int i, int j) { int xRz = findSet(i); int yRz = findSet(j); if (rank[xRz] > rank[yRz]) pset[yRz] = xRz; else { pset[xRz] = yRz; if (rank[xRz] == rank[yRz]) ++rank[yRz]; } }
    static double kruskall() { double cost = 0; makeSet(n); Collections.sort(nodelist); for (Node node : nodelist) { if (!isSameSet(node.from, node.to)) { Union(node.from, node.to); cost += node.w; } } return cost; }
    public static void main(String[] args) throws IOException { Scanner in = new Scanner(System.in); n = in.nextInt(); double[] xcord = new double[n]; double[] ycord = new double[n]; nodelist = new ArrayList<Node>(); for (int i = 0; i < n; ++i) { xcord[i] = in.nextDouble(); ycord[i] = in.nextDouble(); } for (int i = 0; i < n - 1; ++i) { for (int j = i + 1; j < n; ++j) { double dx = xcord[i] - xcord[j]; double dy = ycord[i] - ycord[j]; double d = Math.sqrt(dx * dx + dy * dy); nodelist.add(new Node(d, i, j)); nodelist.add(new Node(d, j, i)); } } System.out.println(String.format("%.2f", kruskall())); }
}

