import java.util.*;

class Freckles {

    public static void main(String[] args) {
        Scanner stdin = new Scanner(System.in);
        int numberOfPoints = stdin.nextInt();
        Point[] faceMap = new Point[numberOfPoints];
        for (int i = 0; i < numberOfPoints; i++) {
            faceMap[i] = new Point(stdin.nextDouble(), stdin.nextDouble());
        }
        drawLinesToFormGroups(faceMap, numberOfPoints);
    }

    public static void drawLinesToFormGroups(Point[] points, int numberOfPoints) {
        int groupsRemaining = numberOfPoints;
        PriorityQueue<Link> links = new PriorityQueue<>();
        for (int i = 0; i < numberOfPoints - 1; i++) {
            for (int j = i + 1; j < numberOfPoints; j++)
                links.add(new Link(i, j, Point.distance(points[i], points[j])));
        }
        double totalDistance = 0;
        while (!links.isEmpty() && groupsRemaining > 1) {
            Link closestLink = links.poll();
            if (closestLink.connectPoints(points)) {
                groupsRemaining--;
                totalDistance += closestLink.getDistance();
            }
        }
        System.out.printf("%.2f\n", totalDistance);
    }
}

class Point {
    private Point parent = this;
    double x, y;

    Point(double x, double y) {
        this.x = x;
        this.y = y;
    }

    public Point findRoot() {
        if (parent != this)
            parent = parent.findRoot();
        return parent;
    }

    public void unite(Point root) {
        root.parent = this;
    }

    public static double distance(Point a, Point b) {
        double dx = a.x - b.x;
        double dy = a.y - b.y;
        return Math.sqrt(dx * dx + dy * dy);
    }
}

class Link implements Comparable<Link> {
    private final int pointIndex1;
    private final int pointIndex2;
    private final double distance;

    Link(int pointIndex1, int pointIndex2, double distance) {
        this.pointIndex1 = pointIndex1;
        this.pointIndex2 = pointIndex2;
        this.distance = distance;
    }

    public double getDistance() {
        return distance;
    }

    @Override
    public int compareTo(Link other) {
        return Double.compare(this.distance, other.distance);
    }

    public boolean connectPoints(Point[] points) {
        Point root1 = points[pointIndex1].findRoot();
        Point root2 = points[pointIndex2].findRoot();

        if (root1 != root2) {
            if (Math.random() > 0.5) root1.unite(root2); // Randomly choose a root to unite to simulate rank comparison. Can be improved based on actual rank comparison if necessary.
            else root2.unite(root1);
            return true;
        }
        return false;
    }
}

