    }

    public Node getEndNode() {
        return endNode;
    }
}

class KruskalAlgorithm {
    private static LinkedList<Set> vertexSets = new LinkedList<>();
    private static LinkedList<Edge> selectedEdges = new LinkedList<>();
    private static LinkedList<Edge> allEdges = new LinkedList<>();

    private static int findSet(Node node) {
        for (int i = 0; i < vertexSets.size(); i++) {
            for (Node n : vertexSets.get(i).getNodes()) {
                if (n.getX() == node.getX() && n.getY() == node.getY()) {
                    return i;
                }
            }
        }
        return -1;
    }

    private static void mergeSets(int setIndex1, int setIndex2) {
        Set set1 = vertexSets.get(setIndex1);
        Set set2 = vertexSets.get(setIndex2);
        set1.getNodes().addAll(set2.getNodes());
        vertexSets.remove(setIndex2);
    }

    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        Graph graph = new Graph(input.nextInt());
        for (int i = 0; i < graph.getSize(); i++) {
            Node node = new Node(input.nextDouble(), input.nextDouble(), i);
            graph.addNode(node, i);
        }
        initializeSets(graph);
        generateAllEdges(graph);
        Collections.sort(allEdges); // Sorting edges based on distance
        kruskalAlgorithm(); // Apply Kruskal's algorithm
        printTotalDistance(); // Print the total distance (weight of MST)
    }

    private static void initializeSets(Graph graph) {
        for (int i = 0; i < graph.getSize(); i++) {
            vertexSets.add(new Set(graph.getNode(i), i));
        }
    }

    private static void generateAllEdges(Graph graph) {
        for (int i = 0; i < graph.getSize(); i++) {
            for (int j = i + 1; j < graph.getSize(); j++) {
                allEdges.add(new Edge(graph.getNode(i), graph.getNode(j)));
            }
        }
    }

    private static void kruskalAlgorithm() {
        for (Edge edge : allEdges) {
            int setIndex1 = findSet(edge.getStartNode());
            int setIndex2 = findSet(edge.getEndNode());
            if (setIndex1 != setIndex2) {
                selectedEdges.add(edge);
                mergeSets(setIndex1, setIndex2);
            }
        }
    }

    private static void printTotalDistance() {
        double result = 0.0;
        for (Edge edge : selectedEdges) {
            result += edge.getDistance();
        }
        System.out.printf("%.2f\n", result);
    }
}

import java.util.*;

class Graph {
    private final int DIM = 1000;
    private List<List<Integer>> adj;
    private int[] color, parent, startTime, finishTime;
    private int time;

    Graph() {
        adj = new ArrayList<>(Collections.nCopies(DIM, null));
        color = new int[DIM];
        parent = new int[DIM];
        startTime = new int[DIM];
        finishTime = new int[DIM];
        Arrays.fill(parent, -1);
    }

    Graph transpose() {
        Graph transposed = new Graph();
        for (int i = 0; i < DIM && this.adj.get(i) != null; i++) {
            transposed.adj.set(i, new LinkedList<>());
        }
        for (int i = 0; i < DIM && this.adj.get(i) != null; i++) {
            for (int node : adj.get(i)) {
                transposed.adj.get(node).add(i);
            }
        }
        return transposed;
    }

    void depthFirstSearch(List<Integer> fst, List<Integer> snd) {
        Arrays.fill(color, 0);
        time = 0;
        for (Integer source : fst) {
            if (color[source] == 0) depthFirstVisit(source, snd);
        }
    }

    private void depthFirstVisit(int source, List<Integer> snd) {
        color[source] = 1;
        startTime[source] = ++time;
        if (adj.get(source) != null) {
            for (int node : adj.get(source)) {
                if (color[node] == 0) {
                    parent[node] = source;
                    depthFirstVisit(node, snd);
                }
            }
        }
        color[source] = 2;
        finishTime[source] = ++time;
        snd.add(0, source);
    }

    PriorityQueue<Integer> findValues(int value) {
        PriorityQueue<Integer> queue = new PriorityQueue<>();
        for (int i = 0; i < DIM && adj.get(i) != null; i++)
            if (parent[i] == value) queue.add(i);
        return queue;
    }

    void makeTree(List<Integer> tree, int value) {
        if (value != -1) tree.add(value);
        PriorityQueue<Integer> queue = findValues(value);
        while (!queue.isEmpty()) {
            makeTree(tree, queue.remove());
        }
    }

    List<List<Integer>> buildTreeForest() {
        List<List<Integer>> treeForest = new ArrayList<>(Collections.nCopies(DIM, null));
        for (int i = 0; i < DIM && adj.get(i) != null; i++) {
            if (parent[i] == -1) {
                List<Integer> tree = new LinkedList<>();
                makeTree(tree, i);
                treeForest.set(i, tree);
            }
        }
        treeForest.removeIf(Objects::isNull);
        return treeForest;
    }

    public void addEdge(int source, int destination) {
        if (adj.get(source) == null) adj.set(source, new LinkedList<>());
        adj.get(source).add(destination);
    }
}

