class Point {
    double x, y;
    int id;

    Point() {}
    Point(double x, double y, int id) {
        this.x = x;
        this.y = y;
        this.id = id;
    }
}

class GraphStructure {
    ArrayList<Point> points;
    int size;

    GraphStructure(int size) {
        this.size = size;
        points = new ArrayList<>(size);
    }

    void addPoint(Point point) {
        points.add(point);
    }
}

class UnionFind {
    ArrayList<ArrayList<Point>> clusters;

    UnionFind() {
        clusters = new ArrayList<>();
    }

    void initialize(GraphStructure graph) {
        for (Point p : graph.points) {
            ArrayList<Point> cluster = new ArrayList<>();
            cluster.add(p);
            clusters.add(cluster);
        }
    }

    int findClusterIndex(Point p) {
        for (int i = 0; i < clusters.size(); i++) {
            for (Point point : clusters.get(i)) {
                if (point.x == p.x && point.y == p.y) return i;
            }
        }
        return -1;
    }

    void unionClusters(int idx1, int idx2) {
        clusters.get(idx1).addAll(clusters.get(idx2));
        clusters.remove(idx2);
    }
}

class Connection implements Comparable<Connection> {
    Point start, end;
    double length;

    Connection(Point start, Point end) {
        this.start = start;
        this.end = end;
        length = Math.hypot(end.x - start.x, end.y - start.y);
    }

    @Override
    public int compareTo(Connection other) {
        return Double.compare(this.length, other.length);
    }
}

class KruskalsOptimization {

    private static double calculateTotalLength(ArrayList<Connection> connections) {
        double total = 0;
        for (Connection conn : connections) {
            total += conn.length;
        }
        return total;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        GraphStructure graph = new GraphStructure(scanner.nextInt());
        for (int i = 0; i < graph.size; i++) {
            graph.addPoint(new Point(scanner.nextDouble(), scanner.nextDouble(), i));
        }

        ArrayList<Connection> allConnections = new ArrayList<>();
        for (int i = 0; i < graph.size; i++) {
            for (int j = i + 1; j < graph.size; j++) {
                allConnections.add(new Connection(graph.points.get(i), graph.points.get(j)));
            }
        }

        allConnections.sort(null);

        UnionFind unionFind = new UnionFind();
        unionFind.initialize(graph);

        ArrayList<Connection> selectedConnections = new ArrayList<>();
        for (Connection conn : allConnections) {
            int clusterIndex1 = unionFind.findClusterIndex(conn.start);
            int clusterIndex2 = unionFind.findClusterIndex(conn.end);
            if (clusterIndex1 != clusterIndex2) {
                selectedConnections.add(conn);
                unionFind.unionClusters(clusterIndex1, clusterIndex2);
            }
        }

        double results = calculateTotalLength(selectedConnections);
        System.out.printf("%.2f\n", results);
    }
}

