class GroupStack {
    int count;
    StackNode top;
    GroupStack() {
        count = 0;
        top = null;
    }
    int stackSize() {
        return count;
    }
    void push(int elem) {
        StackNode newTop = new StackNode(elem);
        newTop.setNext(top);
        top = newTop;
        count++;
    }
    int[] getElements() {
        int[] members = new int[count];
        StackNode current = top;
        for (int i = 0; current != null; current = current.getNext(), i++) {
            members[i] = current.getValue();
        }
        return members;
    }
    GroupStack splitUntil(int value) {
        int item;
        GroupStack newStack = new GroupStack();
        do {
            item = this.pop();
            newStack.push(item);
        } while (item != value);
        return newStack;
    }
    int pop() {
        int val = top.getValue();
        top = top.getNext();
        count--;
        return val;
    }
    boolean isEmpty() {
        return top == null;
    }
}

class StackNode {
    int value;
    StackNode next;
    StackNode(int val) {
        value = val;
        next = null;
    }
    int getValue() { return value; }
    void setNext(StackNode nxt) { next = nxt; }
    StackNode getNext() { return next; }
}

