import java.util.*;

class FreckleCalculator {
    private static double[][] positions;
    private static boolean[][] isCalculated;
    private static double[] closestDistance;
    private static int[] previous;
    private static int totalVertices;

    public static void main(String[] args) {
        Scanner inputScanner = new Scanner(System.in).useLocale(Locale.US);
        int pointCount = inputScanner.nextInt();
        totalVertices = pointCount;
        positions = new double[pointCount][pointCount];
        isCalculated = new boolean[pointCount][pointCount];
        closestDistance = new double[pointCount];
        previous = new int[pointCount];

        double[][] coords = new double[pointCount][2];
        for (int i = 0; i < pointCount; i++) {
            coords[i][0] = inputScanner.nextDouble(); 
            coords[i][1] = inputScanner.nextDouble();
        }
        calculatePositions(coords);
        applyPrimAlgorithm(0);

        System.out.printf(Locale.US, "%.2f\n", calculateTotalDistance());
    }

    private static void calculatePositions(double[][] coordinates) {
        for (int i = 0; i < totalVertices; i++) {
            for (int j = i ; j < totalVertices; j++) {
                if (i != j) {
                    double distance = distanceBetweenPoints(coordinates[i][0], coordinates[j][0], coordinates[i][1], coordinates[j][1]);
                    positions[i][j] = positions[j][i] = distance;
                }
            }
        }
    }

    private static double distanceBetweenPoints(double x1, double x2, double y1, double y2) {
        return Math.sqrt(Math.pow(x1 - x2, 2) + Math.pow(y1 - y2, 2));
    }

    private static void applyPrimAlgorithm(int startingNode) {
        Arrays.fill(closestDistance, Double.MAX_VALUE);
        closestDistance[startingNode] = 0;
        Set<Integer> remainingVertices = new HashSet<>();
        for (int i = 0; i < totalVertices; i++) {
            remainingVertices.add(i);
        }

        while (!remainingVertices.isEmpty()) {
            int nearestVertex = findNearestVertex(remainingVertices);
            remainingVertices.remove(nearestVertex);
            for (int adjacentVertex = 0; adjacentVertex < totalVertices; adjacentVertex++) {
                if (remainingVertices.contains(adjacentVertex) && positions[nearestVertex][adjacentVertex] < closestDistance[adjacentVertex]) {
                    previous[adjacentVertex] = nearestVertex;
                    closestDistance[adjacentVertex] = positions[nearestVertex][adjacentVertex];
                }
            }
        }
    }

    private static int findNearestVertex(Set<Integer> vertices) {
        double minimumDistance = Double.MAX_VALUE;
        int nearestVertex = -1;
        for (Integer vertex : vertices) {
            if (closestDistance[vertex] < minimumDistance) {
                nearestVertex = vertex;
                minimumDistance = closestDistance[vertex];
            }
        }
        return nearestVertex;
    }

    private static double calculateTotalDistance() {
        double totalDistance = 0;
        for (double distance : closestDistance) {
            totalDistance += distance;
        }
        return totalDistance;
    }
}

