class Edge implements Comparable<Edge> {
    public Node a;
    public Node b;
    public double dist;
    Edge(Node a, Node b) {
        this.a = a;
        this.b = b;
        this.dist = Math.sqrt(Math.pow(b.x - a.x, 2) + Math.pow(b.y - a.y, 2));
    }
    @Override public int compareTo(Edge e) {
        if (Double.compare(this.dist, e.dist) < 0) {
            return -1;
        } else if (Double.compare(this.dist, e.dist) > 0) {
            return 1;
        }
        return 0;
    }
}
class SardasKrustall {
    public static LinkedList<Set> sets;
    public static LinkedList<Edge> edges;
    public static LinkedList<Edge> A;
    public static int find(Node node) {
        for (int i = 0; i < sets.size(); i++) {
            for (int j = 0; j < sets.get(i).nodes.size(); j++) {
                if (sets.get(i).nodes.get(j).x == node.x && sets.get(i).nodes.get(j).y == node.y) {
                    return i;
                }
            }
        }
        return -1;
    }
    public static void merge(int a, int b) {
        for (int i = 0; i < sets.get(b).nodes.size(); i++) {
            sets.get(a).nodes.add(sets.get(b).nodes.get(i));
        }
        sets.remove(b);
    }
    public static void resetId() {
        for (int i = 0; i < sets.size(); i++) {
            sets.get(i).id = i;
        }
    }
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        Graph g = new Graph(input.nextInt());
        for (int i = 0; i < g.n; i++) {
            Node n = new Node(input.nextFloat(), input.nextFloat(), i);
            g.addNode(n);
        }
        sets = new LinkedList<Set>();
        for (int i = 0; i < g.n; i++) {
            sets.add(new Set(g.nodes[i], i));
        }
        edges = new LinkedList<Edge>();
        A = new LinkedList<Edge>();
        for (int i = 0; i < g.n; i++) {
            for (int j = i + 1; j < g.n; j++) {
                edges.add(new Edge(g.nodes[i], g.nodes[j]));
            }
        }
        Collections.sort(edges);
        for (Edge e : edges) {
            int a = find(e.a);
            int b = find(e.b);
            if (a != b) {
                A.addLast(e);
                merge(a, b);
            }
        }
        double result = 0.0f;
        for (Edge E : A) {
            result += E.dist;
        }
        System.out.printf("%.2f\n", result);
    }
}

import java.util.*;
class sol {
    Scanner kb;
    sol(Scanner kb) {
        this.kb = kb;
    }
    int N;
    int count;
    boolean[] visited;
    Deque<Integer> order = new LinkedList<Integer>();
    HashMap<Integer, Integer> map = new HashMap<Integer, Integer>();
    LinkedList<Integer> Nodes = new LinkedList<Integer>();
    ArrayList<LinkedList<Integer>> adj = new ArrayList<LinkedList<Integer>>();
    ArrayList<LinkedList<Integer>> tadj = new ArrayList<LinkedList<Integer>>();
    int find_node(int u) {
        if (!map.containsKey(u)) {
            adj.add(new LinkedList<Integer>());
            tadj.add(new LinkedList<Integer>());
            int p = map.size();
            map.put(u, p);
        }
        return map.get(u);
    }
    void read() {
        N = kb.nextInt();
        adj.clear();
        map.clear();
        tadj.clear();
        for (int i = 0; i < N; i++) {
            int u = kb.nextInt();
            u = find_node(u);
            int c = kb.nextInt();
            for (int k = 0; k < c; k++) {
                int v = kb.nextInt();
                v = find_node(v);
                adj.get(u).add(v);
                tadj.get(v).add(u);
            }
        }
        N = map.size();
    }
    void dfs(int u) {
        visited[u] = true;
        for (int v : adj.get(u)) {
            if (!visited[v])
                dfs(v);
        }
        order.addFirst(u);
    }
    void flood_fill(int u) {
        visited[u] = true;
        count++;
        for (int v : tadj.get(u)) {
            if (!visited[v])
                flood_fill(v);
        }
    }
    void solve() {
        visited = new boolean[N];
        order.clear();
        for (int i = 0; i < N; i++)
            if (!visited[i]) dfs(i);
        Arrays.fill(visited, false);
        int B = 0, A = 0;
        for (int u : order) {
            if (!visited[u]) {
                count = 0;
                flood_fill(u);
                if (count >= 4)
                    A++;
                else
                    B += count;
            }
        }
        System.out.printf("%d %d\n", A, B);
    }
}
class pa {
    public static void main(String[] args) {
        Scanner kb = new Scanner(System.in);
        sol s = new sol(kb);
        int c = kb.nextInt();
        for (int i = 1; i <= c; i++) {
            System.out.printf("Caso#%d\n", i);
            s.read();
            s.solve();
        }
    }
}

