import java.util.ArrayList;
import java.util.Scanner;

class Vertex {
    boolean marked;
    double xCoord;
    double yCoord;
    ArrayList<Connection> connections;

    Vertex(double x, double y) {
        marked = false;
        this.xCoord = x;
        this.yCoord = y;
        connections = new ArrayList<>();
    }

    void connect(Connection edge) {
        connections.add(edge);
    }
}

class Network {
    ArrayList<Vertex> vertices;
    double totalInk;

    Network() {
        vertices = new ArrayList<>();
        totalInk = 0.0;
    }

    void addVertex(Vertex vertex) {
        vertices.add(vertex);
    }

    void build() {
        ArrayList<Vertex> queue = new ArrayList<>(vertices);
        while (!queue.isEmpty()) {
            Vertex current = queue.remove(0);
            for (Vertex v : queue) {
                current.connect(createConnection(current, v));
                v.connect(createConnection(v, current));
            }
        }
    }

    Connection createConnection(Vertex start, Vertex end) {
        return new Connection(start, end);
    }

    double executePrim() {
        if (vertices.isEmpty()) return totalInk;
        ArrayList<Vertex> unvisited = new ArrayList<>(vertices);
        ArrayList<Connection> availableEdges = new ArrayList<>();
        Vertex current = unvisited.remove(0);
        current.marked = true;

        while (!unvisited.isEmpty()) {
            double smallest = Double.POSITIVE_INFINITY;
            Connection selectedEdge = null;
            availableEdges.clear();
            availableEdges.addAll(current.connections);
            for (int i = 0; i < availableEdges.size(); i++) {
                Connection edge = availableEdges.get(i);
                if (!edge.destination.marked && edge.distance < smallest) {
                    smallest = edge.distance;
                    selectedEdge = edge;
                }
            }
            if (selectedEdge != null) {
                totalInk += smallest;
                selectedEdge.destination.marked = true;
                current = unvisited.remove(unvisited.indexOf(selectedEdge.destination));
            }
        }
        return totalInk;
    }
}

class Connection {
    double distance;
    Vertex destination;
    Vertex source;

    Connection(Vertex source, Vertex destination) {
        this.source = source;
        this.destination = destination;
        distance = Math.sqrt(Math.pow(source.xCoord - destination.xCoord, 2) + Math.pow(source.yCoord - destination.yCoord, 2));
    }
}

class SimplifiedNetwork {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        Network network = new Network();
        int pointsCount = scanner.nextInt();
        while (pointsCount-- > 0) {
            double x = scanner.nextDouble();
            double y = scanner.nextDouble();
            Vertex vertex = new Vertex(x, y);
            network.addVertex(vertex);
        }
        network.build();
        double requiredInk = network.executePrim();
        System.out.printf("%.2f\n", requiredInk);
    }
}

import java.util.*;
class Pessoa {
    int id;
    int namigos;
    int[] amigos;
    int t;
    boolean visitado;
    Pessoa(int i) {
        id = i;
        visitado = false;
    }
    Pessoa(int i, int n) {
        id = i;
        namigos = n;
        amigos = new int[namigos];
        t = 0;
        visitado = false;
    }
    int pos() {
        int p = 0;
        for (int i = 0; i < amigos.length; i++)
            if (amigos[i] != 0)
                p++;
        return p;
    }
}
class Grafo {
    int nos;
    int tempo;
    Pessoa[] ppl;
    Pessoa[] tppl;
    int ngrupos;
    int nelementos;
    int res;
    int visitados;
    Grafo(int n) {
        nos = n;
        tempo = 0;
        ppl = new Pessoa[n + 1];
        tppl = new Pessoa[n + 1];
        ngrupos = 0;
        nelementos = 0;
        res = 0;
        visitados = 0;
    }
    void criar(Scanner kb) {
        for (int i = 1; i <= nos; i++) {
            ppl[i] = new Pessoa(i);
            tppl[i] = new Pessoa(i, nos);
        }
        for (int i = 0; i < nos; i++) {
            int id = kb.nextInt();
            int nf = kb.nextInt();
            Pessoa nova = new Pessoa(id, nf);
            ppl[id] = nova;
            for (int j = 0; j < nf; j++) {
                int f = kb.nextInt();
                ppl[id].amigos[j] = f;
            }
        }
    }
    void transpor() {
        for (int i = 1; i <= nos; i++) {
            int aux, in;
            for (int j = 0; j < ppl[i].amigos.length; j++) {
                aux = ppl[i].amigos[j];
                in = tppl[aux].pos();
                tppl[aux].amigos[in] = i;
            }
        }
    }
    void dfs() {
        for (int i = 1; i < ppl.length; i++) {
            if (ppl[i].visitado == false)
                dfs_visit(i);
        }
    }
    void dfs_visit(int x) {
        if (ppl[x].visitado == false) {
            ppl[x].visitado = true;
            for (int j = 0; j < ppl[x].amigos.length; j++) {
                dfs_visit(ppl[x].amigos[j]);
            }
            tempo++;
            ppl[x].t = tempo;
        }
    }
    int findMax() {
        int max = -1;
        int indice = -1;
        for (int i = 1; i <= nos; i++)
            if (max < ppl[i].t && tppl[i].visitado == false) {
                max = ppl[i].t;
                indice = i;
            }
        return indice;
    }
    void dfs_t_visit(int x) {
        if (tppl[x].visitado == false) {
            tppl[x].visitado = true;
            visitados++;
            for (int j = 0; j < tppl[x].pos(); j++) {
                dfs_t_visit(tppl[x].amigos[j]);
            }
            nelementos++;
        }
    }
    void dfs_t() {
        while (visitados < nos) {
            int id = findMax();
            if (tppl[id].visitado == false && id != -1) {
                nelementos = 0;
                dfs_t_visit(id);
                if (nelementos >= 4)
                    ngrupos++;
                else
                    res = res + nelementos;
            }
        }
    }
    void print() {
        System.out.println(ngrupos + " " + res);
    }
}
public class Sociologia {
    public static void main(String[] args) {
        Scanner kb = new Scanner(System.in);
        int ncasos = kb.nextInt();
        for (int i = 1; i <= ncasos; i++) {
            int n = kb.nextInt();
            Grafo g = new Grafo(n);
            g.criar(kb);
            g.dfs();
            g.transpor();
            g.dfs_t();
            System.out.println("Caso #" + i);
            g.print();
        }
    }
}

