import java.util.*;
import java.io.*;

class Vertex {
    public boolean mark;
    public double posX;
    public double posY;
    public List<Link> connections;

    Vertex(double posX, double posY) {
        this.mark = false;
        this.posX = posX;
        this.posY = posY;
        connections = new ArrayList<>();
    }

    public void connect(Link l) {
        connections.add(l);
    }
}

class Net {
    public List<Vertex> points;
    public double totalLength;

    Net() {
        points = new ArrayList<>();
        totalLength = 0.0;
    }

    public void insertVertex(Vertex v) {
        points.add(v);
    }

    public void construct() {
        Queue<Vertex> processQueue = new LinkedList<>();
        processQueue.addAll(points);
        Vertex currentPoint;

        while (!processQueue.isEmpty()) {
            currentPoint = processQueue.poll();
            for (Vertex neighbor : processQueue) {
                currentPoint.connect(createLink(currentPoint, neighbor));
                neighbor.connect(createLink(neighbor, currentPoint));
            }
        }
    }

    public Link createLink(Vertex start, Vertex end) {
        return new Link(start, end);
    }

    public double calculateMST() {
        PriorityQueue<Link> edgePriorityQueue = new PriorityQueue<>(Comparator.comparingDouble(o -> o.distance));
        Vertex currentVertex = points.get(0);
        currentVertex.mark = true;

        while (points.stream().anyMatch(v -> !v.mark)) {
            for (Link edge : currentVertex.connections) {
                if (!edge.end.mark) {
                    edgePriorityQueue.add(edge);
                }
            }

            Link shortestLink = edgePriorityQueue.poll();
            while (shortestLink != null && shortestLink.end.mark) {
                shortestLink = edgePriorityQueue.poll();
            }

            if (shortestLink != null) {
                totalLength += shortestLink.distance;
                shortestLink.end.mark = true;
                currentVertex = shortestLink.end;
            }
        }

        return totalLength;
    }
}

class Link implements Comparable<Link> {
    public double distance;
    public Vertex end;
    public Vertex start;

    Link(Vertex start, Vertex end) {
        this.start = start;
        this.end = end;
        distance = Math.hypot(start.posX - end.posX, start.posY - end.posY);
    }

    @Override
    public int compareTo(Link other) {
        return Double.compare(this.distance, other.distance);
    }
}

class NetworkPlanner {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        Net network = new Net();
        int count = scanner.nextInt();
        while (count > 0) {
            double posX = scanner.nextDouble();
            double posY = scanner.nextDouble();
            network.insertVertex(new Vertex(posX, posY));
            count--;
        }
        network.construct();
        double totalInk = network.calculateMST();
        System.out.printf("%.2f\n", totalInk);
    }
}

