public class prob21 {
    static int[] pset;
    static class ramo implements Comparable<ramo> {
        int u;
        int v;
        double w;
        public ramo(int st, int end, double we) {
            u = st;
            v = end;
            w = we;
        }
        @Override public int compareTo(ramo o) {
            if (w > o.w)
                return -1;
            else
                return 1;
        }
    }
    static int findSet(int i) {
        if (pset[i] == i) {
            return i;
        } else {
            return pset[i] = findSet(pset[i]);
        }
    }
    static void unionSet(int i, int j) {
        pset[findSet(i)] = pset[findSet(j)];
    }
    static boolean isSameSet(int i, int j) {
        return findSet(i) == findSet(j);
    }
    public static void initSet(int tamanho) {
        pset = new int[tamanho];
        for (int i = 0; i < tamanho; i++) {
            pset[i] = i;
        }
    }
    public static void main(String[] args) throws Exception {
        Scanner ler = new Scanner(System.in);
        PriorityQueue<ramo> ramoList = new PriorityQueue<ramo>();
        int n = ler.nextInt();
        double[][] cord = new double[n][2];;
        double currLen;
        double yDiff, xDiff;
        double min = 0.0;
        for (int i = 0; i < n; i++) {
            min = 0;
            initSet(n);
            cord[i][0] = ler.nextDouble();
            cord[i][1] = ler.nextDouble();
            for (int j = 0; j < n; j++) {
                for (int k = j + 1; k < n; k++) {
                    xDiff = cord[j][0] - cord[k][0];
                    yDiff = cord[j][1] - cord[k][1];
                    currLen = Math.sqrt(yDiff * yDiff + xDiff * xDiff);
                    ramo e = new ramo(j, k, -currLen);
                    ramoList.add(e);
                }
            }
            while (!ramoList.isEmpty()) {
                ramo e = ramoList.poll();
                if (!isSameSet(e.u, e.v)) {
                    min += -e.w;
                    unionSet(e.u, e.v);
                }
            }
        }
        System.out.printf("%.2f\n", min);
    }
}

import java.util.*;

class Enigma {
    Scanner scanner;
    Enigma(Scanner scanner) {
        this.scanner = scanner;
    }

    int VertexCount;
    int islands;
    boolean[] mark;
    LinkedList<Integer> sequence = new LinkedList<>();
    LinkedList<Integer> VertexList = new LinkedList<>();
    HashMap<Integer, Integer> vertexMap = new HashMap<>();
    List<LinkedList<Integer>> graph = new ArrayList<>();
    List<LinkedList<Integer>> reverseGraph = new ArrayList<>();

    int mapVertex(int vertex) {
        if (!vertexMap.containsKey(vertex)) {
            graph.add(new LinkedList<>());
            reverseGraph.add(new LinkedList<>());
            int index = vertexMap.size();
            vertexMap.put(vertex, index);
        }
        return vertexMap.get(vertex);
    }

    void loadData() {
        VertexCount = scanner.nextInt();
        vertexMap.clear();
        graph.clear();
        reverseGraph.clear();
        for (int i = 0; i < VertexCount; i++) {
            int from = mapVertex(scanner.nextInt());
            int connections = scanner.nextInt();
            for (int j = 0; j < connections; j++) {
                int to = mapVertex(scanner.nextInt());
                graph.get(from).add(to);
                reverseGraph.get(to).add(from);
            }
        }
        VertexCount = vertexMap.size();
    }

    void explore(int vertex) {
        if (mark[vertex]) return;
        mark[vertex] = true;
        for (int adjVertex : graph.get(vertex)) {
            if (!mark[adjVertex]) explore(adjVertex);
        }
        sequence.addFirst(vertex);
    }

    void countComponent(int vertex) {
        islands++;
        mark[vertex] = true;
        for (int adjVertex : reverseGraph.get(vertex)) {
            if (!mark[adjVertex]) countComponent(adjVertex);
        }
    }

    void process() {
        sequence.clear();
        mark = new boolean[VertexCount];
        Arrays.fill(mark, false);
        for (int i = 0; i < VertexCount; i++) explore(i);
        Arrays.fill(mark, false);
        int largeIslands = 0, smallIslands = 0;
        for (int vertex : sequence) {
            if (!mark[vertex]) {
                islands = 0;
                countComponent(vertex);
                if (islands >= 4) largeIslands++;
                else smallIslands += islands;
            }
        }
        System.out.printf("%d %d\n", largeIslands, smallIslands);
    }
}

