    double x;
    double y;
    List<Edge> edges = new LinkedList<>();

    Node(double x, double y) {
        this.x = x;
        this.y = y;
    }

    void addEdge(Node target) {
        edges.add(new Edge(this, target));
    }
}

class Graph {
    List<Node> nodes = new ArrayList<>();
    double ink = 0.0;

    void addNode(Node node) {
        nodes.add(node);
    }

    void buildGraph() {
        for (Node parent : nodes) {
            for (Node child : nodes) {
                if (parent != child) {
                    parent.addEdge(child);
                }
            }
        }
    }

    double computeMinimumSpanningTree() {
        if (nodes.isEmpty()) return 0;

        PriorityQueue<Edge> pq = new PriorityQueue<>(Comparator.comparingDouble(edge -> edge.weight));
        Node startNode = nodes.get(0);
        startNode.visited = true;
        pq.addAll(startNode.edges);

        while (!pq.isEmpty()) {
            Edge closest = pq.poll();
            if (!closest.target.visited) {
                ink += closest.weight;
                closest.target.visited = true;
                for (Edge e : closest.target.edges) {
                    if (!e.target.visited) {
                        pq.add(e);
                    }
                }
            }
        }
        return ink;
    }
}

class Edge {
    Node target;
    double weight;

    Edge(Node from, Node target) {
        this.target = target;
        this.weight = Math.hypot(from.x - target.x, from.y - target.y);
    }
}

