    }
}

class DisjointSet {
    private int[] parent;
    private int[] rank;

    DisjointSet(int size) {
        parent = new int[size];
        rank = new int[size];
        for (int i = 0; i < size; i++) {
            parent[i] = i;
            rank[i] = 0;
        }
    }

    int find(int item) {
        if (item != parent[item]) {
            parent[item] = find(parent[item]);
        }
        return parent[item];
    }

    boolean isSameGroup(int a, int b) {
        return find(a) == find(b);
    }

    void union(int a, int b) {
        int rootA = find(a);
        int rootB = find(b);

        if (rank[rootA] > rank[rootB]) {
            parent[rootB] = rootA;
        } else if (rank[rootA] < rank[rootB]) {
            parent[rootA] = rootB;
        } else {
            parent[rootB] = rootA;
            rank[rootA]++;
        }
    }
}

class MinimumSpanningTree {
    private static List<Edge> edgeList = new ArrayList<>();
    private static int nodesCount;

    private static double calculateMinimumSpanningTree() {
        double mstCost = 0;
        DisjointSet disjointSet = new DisjointSet(nodesCount);
        Collections.sort(edgeList);

        for (Edge edge : edgeList) {
            if (!disjointSet.isSameGroup(edge.source, edge.destination)) {
                disjointSet.union(edge.source, edge.destination);
                mstCost += edge.weight;
            }
        }

        return mstCost;
    }

    public static void main(String[] args) throws IOException {
        Scanner scanner = new Scanner(System.in);
        nodesCount = scanner.nextInt();
        double[] xCoordinates = new double[nodesCount];
        double[] yCoordinates = new double[nodesCount];

        for (int i = 0; i < nodesCount; ++i) {
            xCoordinates[i] = scanner.nextDouble();
            yCoordinates[i] = scanner.nextDouble();
        }

        for (int i = 0; i < nodesCount - 1; ++i) {
            for (int j = i + 1; j < nodesCount; ++j) {
                double distance = Math.sqrt(Math.pow(xCoordinates[i] - xCoordinates[j], 2)
                                            + Math.pow(yCoordinates[i] - yCoordinates[j], 2));
                edgeList.add(new Edge(distance, i, j));
                edgeList.add(new Edge(distance, j, i));
            }
        }

        System.out.printf("%.2f%n", calculateMinimumSpanningTree());
    }
}

