            points[i] = new Point();
        }
    }

    void addPoint(Point point) {
        points[point.index] = point;
    }
}

class DisjointSet {
    LinkedList<Point> members;
    int setId;

    DisjointSet(Point point, int setId) {
        members = new LinkedList<>();
        members.add(point);
        this.setId = setId;
    }
}

class Edge implements Comparable<Edge> {
    Point start, end;
    double distance;

    Edge(Point start, Point end) {
        this.start = start;
        this.end = end;
        this.distance = calculateDistance(start, end);
    }

    private double calculateDistance(Point a, Point b) {
        return Math.sqrt(Math.pow(b.x - a.x, 2) + Math.pow(b.y - a.y, 2));
    }

    @Override
    public int compareTo(Edge o) {
        return Double.compare(this.distance, o.distance);
    }
}

class KruskalsAlgorithm {
    static LinkedList<DisjointSet> sets;
    static LinkedList<Edge> selectedEdges;
    static PriorityQueue<Edge> edgeQueue;

    static int findSetIndexForPoint(Point point) {
        for (int i = 0; i < sets.size(); i++) {
            for (Point member : sets.get(i).members) {
                if (member.x == point.x && member.y == point.y) {
                    return i;
                }
            }
        }
        return -1;
    }

    static void mergeSets(int fromIdx, int toIdx) {
        sets.get(fromIdx).members.addAll(sets.get(toIdx).members);
        sets.remove(toIdx);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        Graph graph = new Graph(scanner.nextInt());
        for (int i = 0; i < graph.size; i++) {
            Point point = new Point(scanner.nextDouble(), scanner.nextDouble(), i);
            graph.addPoint(point);
        }

        sets = initializeSets(graph);
        edgeQueue = initializeEdgeQueue(graph);
        selectedEdges = new LinkedList<>();

        runKruskalsAlgorithm();

        printTotalDistance(selectedEdges);
    }

    private static LinkedList<DisjointSet> initializeSets(Graph graph) {
        LinkedList<DisjointSet> newSets = new LinkedList<>();
        for (Point point : graph.points) {
            newSets.add(new DisjointSet(point, point.index));
        }
        return newSets;
    }

    private static PriorityQueue<Edge> initializeEdgeQueue(Graph graph) {
        PriorityQueue<Edge> newEdgeQueue = new PriorityQueue<>();
        for (int i = 0; i < graph.size; i++) {
            for (int j = i + 1; j < graph.size; j++) {
                newEdgeQueue.add(new Edge(graph.points[i], graph.points[j]));
            }
        }
        return newEdgeQueue;
    }

    private static void runKruskalsAlgorithm() {
        while (!edgeQueue.isEmpty()) {
            Edge currentEdge = edgeQueue.poll();
            int setAIndex = findSetIndexForPoint(currentEdge.start);
            int setBIndex = findSetIndexForPoint(currentEdge.end);

            if (setAIndex != setBIndex) {
                selectedEdges.add(currentEdge);
                mergeSets(setAIndex, setBIndex);
            }
        }
    }

    private static void printTotalDistance(LinkedList<Edge> edges) {
        double totalDistance = edges.stream().mapToDouble(edge -> edge.distance).sum();
        System.out.printf("%.2f\n", totalDistance);
    }
}

