class socio {
    static int lugar(Aluno[] gr, int val, int t) {
        for (int i = 1; i <= t; i++)
            if (gr[i].place == val)
                return i;
        return -1;
    }
    static int dfs(Aluno[] gr, int k, int pl, boolean[][] m, int t) {
        gr[k].estado = true;
        for (int i = 1; i <= t; i++)
            if (!gr[i].estado && m[k][i])
                pl = dfs(gr, i, pl, m, t);
        gr[k].place = pl;
        pl++;
        return pl;
    }
    static int dfsv(Aluno[] gr, int k, int pl, boolean[][] m, int t) {
        gr[k].estado = false;
        for (int i = 1; i <= t; i++)
            if (gr[i].estado && m[i][k])
                pl = dfsv(gr, i, pl, m, t);
        gr[k].place2 = pl;
        pl++;
        return pl;
    }
    public static void main(String[] args) {
        Scanner kb = new Scanner(System.in);
        int cenar = kb.nextInt();
