        if (parent != this) {
            parent = parent.findRoot();
        }
        return parent;
    }

    void union(Point that) {
        that.findRoot().parent = this;
    }

    double distanceTo(Point that) {
        double dx = this.x - that.x;
        double dy = this.y - that.y;
        return Math.sqrt(dx * dx + dy * dy);
    }
