import java.util.*;

class SkinArtwork {
    static int treeDepth = 0;

    public static void main(String[] args) {
        Scanner inputScanner = new Scanner(System.in);
        int pointCount = inputScanner.nextInt();
        SkinPoint[] points = new SkinPoint[pointCount];
        for (int i = 0; i < pointCount; i++) {
            points[i] = new SkinPoint(inputScanner.nextDouble(), inputScanner.nextDouble());
        }
        calculateMinimumSpanningTree(points, pointCount);
    }

    private static void calculateMinimumSpanningTree(SkinPoint[] points, int pointCount) {
        int remainingGroups = pointCount;
        PriorityQueue<Connection> possibleConnections = new PriorityQueue<>();
        for (int i = 0; i < pointCount - 1; i++) {
            for (int j = i + 1; j < pointCount; j++)
                possibleConnections.add(new Connection(i, j, calculateDistance(points[i], points[j])));
        }
        double totalDistance = 0;
        while (!possibleConnections.isEmpty() && remainingGroups > 1) {
            Connection current = possibleConnections.poll();
            SkinPoint startPoint = points[current.startIndex];
            SkinPoint endPoint = points[current.endIndex];
            treeDepth = 0;
            SkinPoint rootStart = startPoint.findRoot();
            int startTreeDepth = treeDepth;
            treeDepth = 0;
            SkinPoint rootEnd = endPoint.findRoot();
            int endTreeDepth = treeDepth;
            if (rootStart != rootEnd) {
                if (startTreeDepth > endTreeDepth)
                    rootStart.mergeRoots(rootEnd);
                else
                    rootEnd.mergeRoots(rootStart);
                remainingGroups--;
                totalDistance += current.distance;
            }
        }
        System.out.printf("%.2f\n", totalDistance);
    }

    private static double calculateDistance(SkinPoint a, SkinPoint b) {
        double deltaX = Math.abs(a.x - b.x);
        double deltaY = Math.abs(a.y - b.y);
        return Math.sqrt(deltaX * deltaX + deltaY * deltaY);
    }
}

class SkinPoint {
    SkinPoint root;
    double x, y;

    SkinPoint(double x, double y) {
        this.root = this;
        this.x = x;
        this.y = y;
    }

    public SkinPoint findRoot() {
        if (root != this) {
            SkinArtwork.treeDepth++;
            root = root.findRoot();
        }
        return root;
    }

    public void mergeRoots(SkinPoint other) {
        other.root = this;
    }
}

class Connection implements Comparable<Connection> {
    int startIndex, endIndex;
    double distance;

    Connection(int start, int end, double distance) {
        this.startIndex = start;
        this.endIndex = end;
        this.distance = distance;
    }

    @Override
    public int compareTo(Connection other) {
        return Double.compare(this.distance, other.distance);
    }

    @Override
    public String toString() {
        return "(" + startIndex + "," + endIndex + "," + distance + ")";
    }
}

