class prob24 {
    static int n;
    static int c;
    static Double total = 0.00;
    static Double[] key;
    static int[] parent;
    static boolean[] vis;
    static boolean[] vis2;
    public static void main(String[] args) throws IOException {
        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        n = Integer.parseInt(in.readLine());
        Double[][] a = new Double[n][2];
        Double[][] dist = new Double[n][n];
        Double[] key = new Double[n];
        int[] parent = new int[n];
        boolean[] vis = new boolean[n];
        boolean[] vis2 = new boolean[n];
        prob24.key = key;
        prob24.parent = parent;
        prob24.vis = vis;
        prob24.vis2 = vis2;
        PriorityQueue<heapi> heap = new PriorityQueue<heapi>(n, new Comparator<heapi>() {
            @Override public int compare(heapi o1, heapi o2) {
                return (o1.valor.compareTo(o2.valor));
            }
        });
        for (int i = 0; i < n; i++) {
            String[] input = in.readLine().split(" ");
            a[i][0] = Double.parseDouble(input[0]);
            a[i][1] = Double.parseDouble(input[1]);
        }
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                Double primeiro = (a[j][0] - a[i][0]) * (a[j][0] - a[i][0]);
                Double segundo = (a[j][1] - a[i][1]) * (a[j][1] - a[i][1]);
                dist[i][j] = Math.sqrt(primeiro + segundo);
                dist[j][i] = Math.sqrt(primeiro + segundo);
            }
        }
        prim(a, dist, heap, 0);
        String result = String.format("%.2f", total);
        System.out.println(result.replaceAll(",", "."));
    }
    static void prim(Double[][] a, Double[][] dist, PriorityQueue<heapi> heap, int x) {
        for (int i = 0; i < n; i++) {
            key[i] = Double.POSITIVE_INFINITY;
            parent[i] = -1;
        }
        key[x] = 0.0;
        heap.add(new heapi(x, key[x]));
        while (!heap.isEmpty()) {
            heapi s = heap.poll();
            int u = s.index;
            if (!vis[u]) {
                vis[u] = true;
                total += key[u];
            }
            for (int i = 0; i < n; i++) {
                if (!vis[i] && dist[u][i] < key[i]) {
                    parent[i] = u;
                    key[i] = dist[u][i];
                    heap.add(new heapi(i, key[i]));
                }
            }
        }
    }
}

import java.util.*;
import java.lang.Math;

class Coordinate {
    double x, y;
    Coordinate(double x, double y) {
        this.x = x;
        this.y = y;
    }
}

class Point extends Coordinate {
    int index;
    Point parent; // Instead of using 'pai', using 'parent' for clarity

    Point(double x, double y, int index) {
        super(x, y);
        this.index = index;
        this.parent = this; // Initializing parent to itself by default
    }
}

class GraphStructure {
    Point[] points;
    GraphStructure(int size) {
        points = new Point[size];
    }

    void addPoint(int index, double x, double y) {
        points[index] = new Point(x, y, index);
    }
}

class Connection implements Comparable<Connection> {
    Point startPoint, endPoint;
    double distance;

    Connection(Point a, Point b) {
        this.startPoint = a;
        this.endPoint = b;
        this.distance = calculateDistance(a, b);
    }

    private double calculateDistance(Point a, Point b) {
        return Math.sqrt(Math.pow(b.x - a.x, 2) + Math.pow(b.y - a.y, 2));
    }

    @Override
    public int compareTo(Connection other) {
        return Double.compare(this.distance, other.distance);
    }
}

class DisjointSet {
    private Map<Point, Integer> pointSetMap = new HashMap<>();

    void makeSet(Point point, int setId) {
        pointSetMap.put(point, setId);
    }

    int findSet(Point point) {
        return pointSetMap.get(point);
    }

    void mergeSets(int firstSetId, int secondSetId) {
        for (Point p : pointSetMap.keySet()) {
            if (pointSetMap.get(p) == secondSetId) {
                pointSetMap.put(p, firstSetId);
            }
        }
    }
}

class MinimalSpanningTree {
    private static List<Connection> constructEdges(GraphStructure graph) {
        List<Connection> edges = new ArrayList<>();
        for (int i = 0; i < graph.points.length; i++) {
            for (int j = i + 1; j < graph.points.length; j++) {
                edges.add(new Connection(graph.points[i], graph.points[j]));
            }
        }
        return edges;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int numberOfPoints = scanner.nextInt();
        GraphStructure graph = new GraphStructure(numberOfPoints);

        for (int i = 0; i < numberOfPoints; i++) {
            double x = scanner.nextDouble();
            double y = scanner.nextDouble();
            graph.addPoint(i, x, y);
        }

        List<Connection> edges = constructEdges(graph);
        Collections.sort(edges);
        DisjointSet disjointSet = new DisjointSet();

        for (int i = 0; i < numberOfPoints; i++) {
            disjointSet.makeSet(graph.points[i], i);
        }

        List<Connection> minimumSpanningTree = new ArrayList<>();
        for (Connection edge : edges) {
            int setA = disjointSet.findSet(edge.startPoint);
            int setB = disjointSet.findSet(edge.endPoint);

            if (setA != setB) {
                minimumSpanningTree.add(edge);
                disjointSet.mergeSets(setA, setB);
            }
        }

        double totalDistance = minimumSpanningTree.stream().mapToDouble(e -> e.distance).sum();
        System.out.printf("%.2f\n", totalDistance);
    }
}

