// Renamed `sol` to `Solution` for clarity.
class Solution {
    private final Scanner scanner;
    private int nodeCount;
    private boolean[] visited;
    private Deque<Integer> topologicalOrder = new LinkedList<>();
    private Map<Integer, Integer> indexMap = new HashMap<>();
    private List<List<Integer>> adjacencyList = new ArrayList<>();
    private List<List<Integer>> reversedAdjList = new ArrayList<>();
    private int componentSize;

    Solution(Scanner scanner) {
        this.scanner = scanner;
    }

    // Finding or creating a node's index
    private int findOrCreateNodeIndex(int node) {
        if (!indexMap.containsKey(node)) {
            int index = indexMap.size();
            adjacencyList.add(new LinkedList<>());
            reversedAdjList.add(new LinkedList<>());
            indexMap.put(node, index);
        }
        return indexMap.get(node);
    }

    // Reading and initializing the graph from input
    void readInput() {
        nodeCount = scanner.nextInt();
        indexMap.clear();
        adjacencyList.clear();
        reversedAdjList.clear();
        for (int i = 0; i < nodeCount; i++) {
            int from = findOrCreateNodeIndex(scanner.nextInt());
            int edges = scanner.nextInt();
            for (int j = 0; j < edges; j++) {
                int to = findOrCreateNodeIndex(scanner.nextInt());
                adjacencyList.get(from).add(to);
                reversedAdjList.get(to).add(from);
            }
        }
        nodeCount = indexMap.size(); // Updating node count to unique nodes.
    }

    // Depth-First Search to populate `topologicalOrder`
    private void dfs(int node) {
        if (visited[node]) return;
        visited[node] = true;
        for (int nextNode : adjacencyList.get(node)) {
            if (!visited[nextNode]) dfs(nextNode);
        }
        topologicalOrder.addFirst(node);
    }

    // Flood Fill to count reachable nodes in the reversed graph
    private void floodFill(int node) {
        componentSize++;
        visited[node] = true;
        for (int nextNode : reversedAdjList.get(node)) {
            if (!visited[nextNode]) floodFill(nextNode);
        }
    }

    // Solving the problem based on DFS and Flood Fill
    void process() {
        topologicalOrder.clear();
        visited = new boolean[nodeCount];
        for (int i = 0; i < nodeCount; i++) dfs(i);

        Arrays.fill(visited, false);
        int largeComponents = 0, smallComponentsSize = 0;
        for (int node : topologicalOrder) {
            if (!visited[node]) {
                componentSize = 0;
                floodFill(node);
                if (componentSize >= 4) largeComponents++;
                else smallComponentsSize += componentSize;
            }
        }
        System.out.printf("%d %d\n", largeComponents, smallComponentsSize);
    }
}

import java.util.*;
import java.lang.*;
class Graph {
    public final Integer DIM = 1000;
    int[] startTime, finishTime;
    int[] color, parent;
    LinkedList<Integer>[] adj = null;
    int time;
    @SuppressWarnings("unchecked") Graph() {
        color = new int[DIM];
        adj = new LinkedList[DIM];
        parent = new int[DIM];
        finishTime = new int[DIM];
        startTime = new int[DIM];
    }
    @SuppressWarnings("unchecked") Graph transpose() {
        Graph transposed = new Graph();
        for (int i = 0; this.adj[i] != null; i++)
            transposed.adj[i] = new LinkedList<Integer>();
        for (int i = 0; this.adj[i] != null; i++) {
            Iterator<Integer> it = adj[i].iterator();
            while (it.hasNext()) {
                int node = it.next();
                transposed.adj[node].addLast(i);
            }
        }
        return transposed;
    }
    @SuppressWarnings("unchecked") void depthFirstSearch(LinkedList<Integer> fst, LinkedList<Integer> snd) {
        Arrays.fill(finishTime, -1);
        time = 0;
        Arrays.fill(startTime, -1);
        Arrays.fill(color, 0);
        Arrays.fill(parent, -1);       
        Iterator<Integer> it = fst.iterator();
        while (it.hasNext()) {
            int source = it.next();
            if (color[source] == 0)
                depthFirstVisit(source, snd);
        }
    }
    @SuppressWarnings("unchecked") void depthFirstVisit(int source, LinkedList<Integer> snd) {
        startTime[source] = time;
        time += 1;
        color[source] = 1;
        Iterator<Integer> it = adj[source].iterator();
        while (it.hasNext()) {
            int node = it.next();
            if (color[node] == 0) {
                parent[node] = source;
                depthFirstVisit(node, snd);
            }
        }        
        color[source] = 2;
        time += 1;
        finishTime[source] = time;
        snd.addFirst(source);
    }
    @SuppressWarnings("unchecked") void makeTree(LinkedList<Integer> tree, int value) {
        if (value != -1)
            tree.add(value);
        PriorityQueue<Integer> fila = new PriorityQueue<Integer>();
        fila = findValues(value, parent);
        while (!fila.isEmpty()) {
            int newValue = fila.remove();
            makeTree(tree, newValue);
        }
    }
    @SuppressWarnings("unchecked") PriorityQueue<Integer> findValues(int value, int[] vtr) {
        PriorityQueue<Integer> fila = new PriorityQueue<Integer>();
        for (int i = 0; adj[i] != null; i++)
            if (vtr[i] == value)
                fila.add(i);
        return fila;
    }
    @SuppressWarnings("unchecked") LinkedList<Integer>[] buildTreeForest() {
        LinkedList<Integer>[] tree = (LinkedList<Integer>[]) new LinkedList[DIM];
        for (int i = 0; adj[i] != null; i++) {
            if (parent[i] == -1) {
                int aux = 0;
                for (int j = 0; tree[j] != null; j++)
                    aux++;
                tree[aux] = new LinkedList<Integer>();
                makeTree(tree[aux], i);
            }
        }
        return tree;
    }
}
