import java.util.*;

class Freckles {
    static double[][] matrix;
    static boolean[][] visited;
    static double[] dist;
    static int[] pred;
    static int vertexCount;

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in).useLocale(Locale.US);
        int n = vertexCount = in.nextInt();
        matrix = new double[n][n];
        visited = new boolean[n][n];
        dist = new double[n];
        Arrays.fill(dist, Double.MAX_VALUE);
        pred = new int[n];
        double[][] coordinates = new double[n][2];

        for (int i = 0; i < n; i++) {
            coordinates[i] = new double[] {in.nextDouble(), in.nextDouble()};
        }

        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                matrix[i][j] = matrix[j][i] = calc(coordinates[i][0], coordinates[j][0], coordinates[i][1], coordinates[j][1]);
            }
        }

        implementPrimAlgorithm(matrix, 0);

        double sum = Arrays.stream(dist).sum();
        System.out.printf(Locale.US, "%.2f\n", sum);
    }

    private static double calc(double xi, double xj, double yi, double yj) {
        double deltaX = xi - xj;
        double deltaY = yi - yj;
        return Math.sqrt(deltaX * deltaX + deltaY * deltaY);
    }

    private static void implementPrimAlgorithm(double[][] graph, int sourceVertex) {
        PriorityQueue<Integer> queue = new PriorityQueue<>(Comparator.comparingDouble(node -> dist[node]));
        dist[sourceVertex] = 0;
        queue.add(sourceVertex);

        while (!queue.isEmpty()) {
            int u = queue.poll();
            for (int v = 0; v < vertexCount; v++) {
                if (graph[u][v] != 0 && dist[u] + graph[u][v] < dist[v]) {
                    dist[v] = graph[u][v];
                    pred[v] = u;
                    queue.add(v);
                }
            }
        }
    }
}

import java.util.*;

class Freckles {
    private static double[][] adjacencyMatrix;
    private static double[] minimumDistanceToTree;
    private static int[] predecessor;
    private static int verticesCount;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in).useLocale(Locale.US);
        int totalVertices = scanner.nextInt();
        verticesCount = totalVertices;
        adjacencyMatrix = new double[totalVertices][totalVertices];
        minimumDistanceToTree = new double[totalVertices];
        predecessor = new int[totalVertices];
        double[][] coordinates = new double[totalVertices][2];

        for (int i = 0; i < totalVertices; i++) {
            coordinates[i][0] = scanner.nextDouble();
            coordinates[i][1] = scanner.nextDouble();
        }

        buildAdjacencyMatrix(coordinates);
        applyPrimAlgorithm(0);
        printTotalMinimumDistance();
    }

    private static void buildAdjacencyMatrix(double[][] coordinates) {
        for (int i = 0; i < verticesCount; i++) {
            for (int j = i; j < verticesCount; j++) {
                if (i != j) {
                    double distance = calculateDistance(coordinates[i], coordinates[j]);
                    adjacencyMatrix[j][i] = adjacencyMatrix[i][j] = distance;
                }
            }
        }
    }

    private static double calculateDistance(double[] pointI, double[] pointJ) {
        return Math.sqrt(Math.pow(pointI[0] - pointJ[0], 2) + Math.pow(pointI[1] - pointJ[1], 2));
    }

    private static void applyPrimAlgorithm(int startingVertex) {
        boolean[] addedToTree = new boolean[verticesCount];
        Arrays.fill(minimumDistanceToTree, Double.MAX_VALUE);
        minimumDistanceToTree[startingVertex] = 0;
        predecessor[startingVertex] = -1;

        for (int count = 0; count < verticesCount - 1; count++) {
            int closestVertex = findClosestVertex(minimumDistanceToTree, addedToTree);
            addedToTree[closestVertex] = true;

            for (int vertexIndex = 0; vertexIndex < verticesCount; vertexIndex++) {
                if (adjacencyMatrix[closestVertex][vertexIndex] > 0 && !addedToTree[vertexIndex]
                        && adjacencyMatrix[closestVertex][vertexIndex] < minimumDistanceToTree[vertexIndex]) {
                    predecessor[vertexIndex] = closestVertex;
                    minimumDistanceToTree[vertexIndex] = adjacencyMatrix[closestVertex][vertexIndex];
                }
            }
        }
    }

    private static int findClosestVertex(double[] distance, boolean[] addedToTree) {
        double minDistance = Double.MAX_VALUE;
        int minIndex = -1;

        for (int vertexIndex = 0; vertexIndex < verticesCount; vertexIndex++) {
            if (!addedToTree[vertexIndex] && distance[vertexIndex] < minDistance) {
                minDistance = distance[vertexIndex];
                minIndex = vertexIndex;
            }
        }
        return minIndex;
    }

    private static void printTotalMinimumDistance() {
        double sum = 0;
        for (int i = 0; i < verticesCount; i++) {
            sum += minimumDistanceToTree[i];
        }
        System.out.printf(Locale.US, "%.2f\n", sum);
    }
}

import java.util.LinkedList;
import java.util.Scanner;

class LocationNode {
    double x, y;
    boolean visited = false;
    LinkedList<ConnectionEdge> connections = new LinkedList<>();

    LocationNode(double x, double y) {
        this.x = x;
        this.y = y;
    }

    void connect(LocationNode other) {
        ConnectionEdge edge = new ConnectionEdge(this, other);
        this.connections.add(edge);
        other.connections.add(new ConnectionEdge(other, this));
    }
}

class ConnectionEdge {
    LocationNode source, target;
    double distance;

    ConnectionEdge(LocationNode from, LocationNode to) {
        this.source = from;
        this.target = to;
        this.distance = Math.hypot(from.x - to.x, from.y - to.y); // More direct way to calculate Euclidean distance.
    }
}

class MapGraph {
    LinkedList<LocationNode> locations = new LinkedList<>();
    double totalDistance = 0.0;

    void addLocation(double x, double y) {
        LocationNode newNode = new LocationNode(x, y);
        locations.add(newNode);
    }

    void createConnections() {
        LinkedList<LocationNode> queue = new LinkedList<>(locations);
        while (!queue.isEmpty()) {
            LocationNode current = queue.poll();
            queue.forEach(other -> current.connect(other));
        }
    }

    double executePrim() {
        LinkedList<LocationNode> unvisited = new LinkedList<>(locations);
        LocationNode startNode = unvisited.poll();
        assert startNode != null;
        startNode.visited = true;

        while (!unvisited.isEmpty()) {
            ConnectionEdge shortestEdge = null;
            double shortestDistance = Double.POSITIVE_INFINITY;

            for (LocationNode from : locations) {
                if (from.visited) {
                    for (ConnectionEdge e : from.connections) {
                        if (!e.target.visited && e.distance < shortestDistance) {
                            shortestDistance = e.distance;
                            shortestEdge = e;
                        }
                    }
                }
            }

            if (shortestEdge != null) {
                shortestEdge.target.visited = true;
                unvisited.remove(shortestEdge.target);
                totalDistance += shortestDistance;
            }
        }
        return totalDistance;
    }
}

class SimplifiedSardas {
    public static void main(String[] args) {
        try (Scanner input = new Scanner(System.in)) { // Try-with-resources for Scanner to ensure it is closed properly.
            MapGraph graph = new MapGraph();
            int nodesCount = input.nextInt();

            for (int i = 0; i < nodesCount; i++) {
                double x = input.nextDouble();
                double y = input.nextDouble();
                graph.addLocation(x, y);
            }

            graph.createConnections();
            double inkRequired = graph.executePrim();
            System.out.printf("%.2f\n", inkRequired);
        }
    }
}

