import java.util.Scanner;
import java.util.Locale;

class Graph {
    private double[][] edges;
    private double[] shortestDistances;
    private int[] predecessor;
    private int numVertices;

    public Graph(int numVertices) {
        this.numVertices = numVertices;
        edges = new double[numVertices][numVertices];
        shortestDistances = new double[numVertices];
        predecessor = new int[numVertices];
    }

    public void initialize(double[][] coordinates) {
        for (int i = 0; i < numVertices; i++) {
            for (int j = i; j < numVertices; j++) {
                if (i != j) {
                    edges[j][i] = edges[i][j] = calculateDistance(coordinates[i][0], coordinates[j][0], coordinates[i][1], coordinates[j][1]);
                }
            }
        }
    }

    public static double calculateDistance(double xi, double xj, double yi, double yj) {
        return Math.sqrt(Math.pow(xi - xj, 2) + Math.pow(yi - yj, 2));
    }

    public double computeMinimumSpanningTree() {
        boolean[] added = new boolean[numVertices];
        for (int i = 0; i < numVertices; i++) {
            shortestDistances[i] = Double.MAX_VALUE;
            added[i] = false;
        }

        shortestDistances[0] = 0;
        predecessor[0] = -1;

        for (int i = 0; i < numVertices - 1; i++) {
            int nearestVertex = findMinimumDistance(shortestDistances, added);
            added[nearestVertex] = true;

            for (int vertexIndex = 0; vertexIndex < numVertices; vertexIndex++) {
                if (!added[vertexIndex] && edges[nearestVertex][vertexIndex] != 0 && shortestDistances[nearestVertex] != Double.MAX_VALUE && shortestDistances[nearestVertex] + edges[nearestVertex][vertexIndex] < shortestDistances[vertexIndex]) {
                    predecessor[vertexIndex] = nearestVertex;
                    shortestDistances[vertexIndex] = edges[nearestVertex][vertexIndex];
                }
            }
        }

        double sum = 0;
        for (double distance : shortestDistances) {
            sum += distance;
        }
        return sum;
    }

    private int findMinimumDistance(double[] dist, boolean[] added) {
        double min = Double.MAX_VALUE;
        int minIndex = -1;

        for (int i = 0; i < numVertices; i++) {
            if (!added[i] && dist[i] < min) {
                min = dist[i];
                minIndex = i;
            }
        }

        return minIndex;
    }
}

