        while (q.size() > 0) {
            min = Double.MAX_VALUE;
            for (int i = 1; i <= n; i++)
                if (q.contains(i) && nodes[i].distance < min) {
                    min = nodes[i].distance;
                    menor = i;
                }
            q.removeFirstOccurrence(menor);
            u = menor;
            for (int w : nodes[u].adj) {
                double p = peso(u, w);
                if (q.contains(w) && p < nodes[w].distance) {
                    nodes[w].pai = u;
                    nodes[w].distance = p;
                }
            }
        }
    }
}
