import java.util.*;

class FreckleConnectivity {

    private static double[][] adjacencyMatrix;
    private static double[] minimumDistances;
    private static boolean[] addedVertices;
    private static final int INFINITY = Integer.MAX_VALUE;
    private static int vertexCount;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in).useLocale(Locale.US);
        vertexCount = scanner.nextInt();
        adjacencyMatrix = new double[vertexCount][vertexCount];
        minimumDistances = new double[vertexCount];
        addedVertices = new boolean[vertexCount];
        double[][] coordinates = new double[vertexCount][2];

        for (int i = 0; i < vertexCount; i++) {
            coordinates[i][0] = scanner.nextDouble(); // X coordinate
            coordinates[i][1] = scanner.nextDouble(); // Y coordinate
        }

        buildAdjacencyMatrix(coordinates);

        System.out.printf(Locale.US, "%.2f\n", computeMinimumSpanningTreeCost());
    }

    private static void buildAdjacencyMatrix(double[][] coordinates) {
        for (int i = 0; i < vertexCount; i++) {
            for (int j = i + 1; j < vertexCount; j++) {
                double distance = calculateDistance(coordinates[i][0], coordinates[j][0], coordinates[i][1], coordinates[j][1]);
                adjacencyMatrix[i][j] = distance;
                adjacencyMatrix[j][i] = distance;
            }
        }
    }

    private static double calculateDistance(double x1, double x2, double y1, double y2) {
        return Math.sqrt(Math.pow(x1 - x2, 2) + Math.pow(y1 - y2, 2));
    }

    private static double computeMinimumSpanningTreeCost() {
        Arrays.fill(minimumDistances, INFINITY);
        minimumDistances[0] = 0;
        double totalCost = 0;

        for (int i = 0; i < vertexCount; i++) {
            int nearestVertex = findNearestVertex(minimumDistances, addedVertices);
            addedVertices[nearestVertex] = true;
            totalCost += minimumDistances[nearestVertex];

            for (int vertex = 0; vertex < vertexCount; vertex++) {
                if (!addedVertices[vertex] && adjacencyMatrix[nearestVertex][vertex] < minimumDistances[vertex]) {
                    minimumDistances[vertex] = adjacencyMatrix[nearestVertex][vertex];
                }
            }
        }
        return totalCost;
    }

    private static int findNearestVertex(double[] distances, boolean[] addedVertices) {
        double minimumDistance = INFINITY;
        int nearestVertexIndex = -1;

        for (int vertexIndex = 0; vertexIndex < vertexCount; vertexIndex++) {
            if (!addedVertices[vertexIndex] && distances[vertexIndex] < minimumDistance) {
                nearestVertexIndex = vertexIndex;
                minimumDistance = distances[vertexIndex];
            }
        }
        return nearestVertexIndex;
    }
}

