    static int l;
    static String linha;
    static char[][] matriz;
    static Node3[][] nodes;
    static int distMax = -1;
    static int distMin;
    static void bfs() {
        LinkedList<Integer> x = new LinkedList<Integer>();
        LinkedList<Integer> y = new LinkedList<Integer>();
        for (int i = 0; i < l; i++)
            for (int j = 0; j < c; j++)
                if (matriz[i][j] != '#') {
                    x.add(i);
                    y.add(j);
                    nodes[i][j].visited = true;
                    nodes[i][j].distance = 0;
                }
        while (x.size() > 0) {
            int u = x.removeFirst();
            int v = y.removeFirst();
            if (v < c - 1)
                if (!nodes[u][v + 1].visited) {
                    x.add(u);
                    y.add(v + 1);
                    nodes[u][v + 1].visited = true;
                    nodes[u][v + 1].distance = nodes[u][v].distance + 1;
                }
            if (v > 0)
                if (!nodes[u][v - 1].visited) {
                    x.add(u);
                    y.add(v - 1);
                    nodes[u][v - 1].visited = true;
                    nodes[u][v - 1].distance = nodes[u][v].distance + 1;
                }
            if (u < l - 1)
                if (!nodes[u + 1][v].visited) {
                    x.add(u + 1);
                    y.add(v);
                    nodes[u + 1][v].visited = true;
                    nodes[u + 1][v].distance = nodes[u][v].distance + 1;
                }
            if (u > 0)
                if (!nodes[u - 1][v].visited) {
                    x.add(u - 1);
                    y.add(v);
                    nodes[u - 1][v].visited = true;
                    nodes[u - 1][v].distance = nodes[u][v].distance + 1;
                }
        }
    }
