import java.util.*;

class Position {
    double xCoordinate;
    double yCoordinate;
    Position parent;
    int identifier;

    Position() {}

    Position(double x, double y, int identifier) {
        this.identifier = identifier;
        this.xCoordinate = x;
        this.yCoordinate = y;
        this.parent = null;
    }
}

class VertexSet {
    List<Position> vertices;
    int setId;

    VertexSet(Position vertex, int setId) {
        vertices = new LinkedList<>();
        vertices.add(vertex);
        this.setId = setId;
    }
}

class ConnectiveGraph {
    int vertexCount;
    Position[] vertices;

    ConnectiveGraph(int size) {
        this.vertexCount = size;
        vertices = new Position[size];
        for (int i = 0; i < size; i++) {
            vertices[i] = new Position();
        }
    }

    void addVertex(Position vertex, int index) {
        vertices[index] = vertex;
    }
}

class Link implements Comparable<Link>{
    Position startVertex;
    Position endVertex;
    double distance;

    Link(Position start, Position end) {
        this.startVertex = start;
        this.endVertex = end;
        this.distance = calculateDistance(start, end);
    }

    private double calculateDistance(Position a, Position b) {
        return Math.sqrt(Math.pow(b.xCoordinate - a.xCoordinate, 2) + Math.pow(b.yCoordinate - a.yCoordinate, 2));
    }

    @Override
    public int compareTo(Link other) {
        return Double.compare(this.distance, other.distance);
    }
}

class MinimalSpanningTree {
    static List<VertexSet> allSets;
    static List<Link> selectedLinks;
    static List<Link> allLinks;

    static int locateVertexSet(Position vertex) {
        for (int i = 0; i < allSets.size(); i++) {
            for (Position v : allSets.get(i).vertices) {
                if (v.xCoordinate == vertex.xCoordinate && v.yCoordinate == vertex.yCoordinate) {
                    return i;
                }
            }
        }
        return -1;
    }

    static void unionSets(int sourceSet, int destinationSet) {
        allSets.get(sourceSet).vertices.addAll(allSets.get(destinationSet).vertices);
        allSets.remove(destinationSet);
    }

    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        ConnectiveGraph graph = new ConnectiveGraph(input.nextInt());

        for (int i = 0; i < graph.vertexCount; i++) {
            Position vertex = new Position(input.nextDouble(), input.nextDouble(), i);
            graph.addVertex(vertex, i);
        }

        selectedLinks = new LinkedList<>();
        allLinks = new LinkedList<>();
        allSets = new LinkedList<>();

        for (int i = 0; i < graph.vertexCount; i++) {
            allSets.add(new VertexSet(graph.vertices[i], i));
            for (int j = i + 1; j < graph.vertexCount; j++) {
                allLinks.add(new Link(graph.vertices[i], graph.vertices[j]));
            }
        }

        Collections.sort(allLinks);
        for (Link edge : allLinks) {
            int sourceSet = locateVertexSet(edge.startVertex);
            int destinationSet = locateVertexSet(edge.endVertex);
            if (sourceSet != destinationSet) {
                selectedLinks.add(edge);
                unionSets(sourceSet, destinationSet);
            }
        }

        double totalDistance = 0.0;
        for (Link link : selectedLinks) {
            totalDistance += link.distance;
        }
        System.out.printf("%.2f\n", totalDistance);
    }
}

