import java.util.*;
import java.io.*;

class Vertex {
    double posX, posY;
    List<Bridge> connections = new ArrayList<>();
    boolean marked = false;

    Vertex(double x, double y) {
        posX = x;
        posY = y;
    }

    void attach(Bridge edge) {
        connections.add(edge);
    }
}

class Network {
    List<Vertex> vertices = new ArrayList<>();
    double totalLength = 0;

    void addVertex(Vertex vertex) {
        vertices.add(vertex);
    }

    Bridge link(Vertex start, Vertex end) {
        return new Bridge(start, end);
    }

    void buildNetwork() {
        List<Vertex> unconnected = new ArrayList<>(vertices);
        Vertex baseVertex;
        while (!unconnected.isEmpty()) {
            baseVertex = unconnected.remove(0);
            for (Vertex v : unconnected) {
                baseVertex.attach(link(baseVertex, v));
                v.attach(link(v, baseVertex));
            }
        }
    }

    double executePrim() {
        PriorityQueue<Bridge> edgeQueue = new PriorityQueue<>(Comparator.comparingDouble(e -> e.distance));
        Vertex current = vertices.get(0);
        current.marked = true;
        updateQueue(edgeQueue, current);

        while (!edgeQueue.isEmpty()) {
            Bridge shortest = edgeQueue.poll();
            assert shortest != null;
            if (!shortest.to.marked) {
                totalLength += shortest.distance;
                shortest.to.marked = true;
                updateQueue(edgeQueue, shortest.to);
            }
        }

        return totalLength;
    }

    void updateQueue(PriorityQueue<Bridge> edgeQueue, Vertex vertex) {
        vertex.connections.forEach(edge -> {
            if (!edge.to.marked) {
                edgeQueue.add(edge);
            }
        });
    }
}

class Bridge implements Comparable<Bridge> {
    Vertex from, to;
    double distance;

    Bridge(Vertex f, Vertex t) {
        from = f;
        to = t;
        distance = Math.hypot(f.posX - t.posX, f.posY - t.posY);
    }

    @Override
    public int compareTo(Bridge other) {
        return Double.compare(this.distance, other.distance);
    }
}

class InkSaver {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        Network map = new Network();
        int count = scanner.nextInt();
        while (count-- > 0) {
            double x = scanner.nextDouble(), y = scanner.nextDouble();
            map.addVertex(new Vertex(x, y));
        }
        map.buildNetwork();
        System.out.printf("%.2f\n", map.executePrim());
    }
}

