import java.util.*;
import java.io.*;

class Point {
    boolean marked;
    double coordX, coordY;
    List<Connection> connections;

    Point(double x, double y) {
        marked = false;
        coordX = x;
        coordY = y;
        connections = new ArrayList<>();
    }

    void link(Connection con) {
        connections.add(con);
    }
}

class Mesh {
    List<Point> points;
    double totalLength;

    Mesh() {
        points = new ArrayList<>();
        totalLength = 0.0;
    }

    void addPoint(Point point) {
        points.add(point);
    }

    void establishLinks() {
        Queue<Point> queue = new LinkedList<>(points);

        while (!queue.isEmpty()) {
            Point current = queue.poll();
            queue.forEach(other -> {
                current.link(new Connection(current, other));
                other.link(new Connection(other, current));
            });
        }
    }

    Connection createConnection(Point start, Point end) {
        return new Connection(start, end);
    }

    double applyPrim() {
        if (points.isEmpty()) return 0;

        Queue<Point> unvisitedPoints = new LinkedList<>(points);
        List<Connection> potentialConnections = new ArrayList<>();
        Point currentPoint = unvisitedPoints.poll();
        assert currentPoint != null;
        currentPoint.marked = true;

        while (!unvisitedPoints.isEmpty()) {
            double shortest = Double.POSITIVE_INFINITY;
            Connection shortestCon = null;

            potentialConnections.clear();
            potentialConnections.addAll(currentPoint.connections);
            for (Connection con : potentialConnections) {
                if (!con.end.marked && con.length < shortest) {
                    shortest = con.length;
                    shortestCon = con;
                }
            }

            if (shortestCon != null) {
                totalLength += shortest;
                shortestCon.end.marked = true;
                currentPoint = shortestCon.end;
                unvisitedPoints.remove(shortestCon.end);
            }
        }

        return totalLength;
    }
}

class Connection {
    double length;
    Point end, start;

    Connection(Point start, Point end) {
        this.end = end;
        this.start = start;
        length = Math.hypot(start.coordX - end.coordX, start.coordY - end.coordY);
    }
}

class PathBuilder {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        Mesh mesh = new Mesh();
        int count = scanner.nextInt();

        while (count-- > 0) {
            double x = scanner.nextDouble();
            double y = scanner.nextDouble();
            mesh.addPoint(new Point(x, y));
        }

        mesh.establishLinks();
        double inkUsage = mesh.applyPrim();
        System.out.printf("%.2f%n", inkUsage);
    }
}

