import java.util.*;

class DotsConnection {
    static int depth = 0;

    public static void main(String[] args) {
        Scanner inputScanner = new Scanner(System.in);
        int totalPoints = inputScanner.nextInt();
        Position[] positionsArray = new Position[totalPoints];
        for (int index = 0; index < totalPoints; index++) {
            positionsArray[index] = new Position(inputScanner.nextDouble(), inputScanner.nextDouble());
        }
        calculateConnections(positionsArray, totalPoints);
    }

    private static void calculateConnections(Position[] coordinates, int count) {
        int componentsCount = count;
        PriorityQueue<Connection> priorityQueue = new PriorityQueue<>();
        for (int currentIndex = 0; currentIndex < count; currentIndex++) {
            for (int nextIndex = currentIndex + 1; nextIndex < count; nextIndex++) {
                priorityQueue.add(new Connection(currentIndex, nextIndex, calculateDistance(coordinates[currentIndex], coordinates[nextIndex])));
            }
        }

        double totalDistance = 0.0;
        while (!priorityQueue.isEmpty() && componentsCount > 1) {
            Connection closestConnection = priorityQueue.poll();
            depth = 0;
            Position root1 = findRoot(coordinates[closestConnection.point1]);
            int depth1 = depth;
            depth = 0;
            Position root2 = findRoot(coordinates[closestConnection.point2]);
            int depth2 = depth;
            if (!root1.equals(root2)) {
                if (depth1 > depth2) root1.merge(root2);
                else root2.merge(root1);

                componentsCount--;
                totalDistance += closestConnection.distance;
            }
        }
        System.out.printf("%.2f\n", totalDistance);
    }

    private static double calculateDistance(Position position1, Position position2) {
        double xComponent = Math.abs(position1.x - position2.x);
        double yComponent = Math.abs(position1.y - position2.y);
        return Math.sqrt(xComponent * xComponent + yComponent * yComponent);
    }

    private static Position findRoot(Position position) {
        if (position.equals(position.previous)) return position;
        else {
            depth++;
            return position.findAncestor();
        }
    }
}

class Position {
    Position previous;
    double x, y;

    Position(double coordinateX, double coordinateY) {
        this.x = coordinateX;
        this.y = coordinateY;
        this.previous = this;
    }

    Position findAncestor() {
        if (!previous.equals(this)) {
            DotsConnection.depth++;
            previous = previous.findAncestor();
        }
        return previous;
    }

    void merge(Position other) {
        other.previous = this;
    }
}

class Connection implements Comparable<Connection> {
    int point1, point2;
    double distance;

    Connection(int p1, int p2, double dist) {
        this.point1 = p1;
        this.point2 = p2;
        this.distance = dist;
    }

    @Override
    public int compareTo(Connection other) {
        return Double.compare(this.distance, other.distance);
    }
}

