}
class Grafo {
    int sizeV;
    int sizeA;
    Vertex[] vertex;
    int[] visitado;
    Grafo(int tamanho) {
        sizeV = tamanho;
        vertex = new Vertex[tamanho];
        visitado = new int[tamanho];
        for (int i = 0; i < tamanho; i++) {
            vertex[i] = new Vertex();
            visitado[i] = 0;
        }
