public class Ex21 {
    static UndirectedGraph<Integer> primed;
    static boolean[] visited = new boolean[101];
    static double dou;
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        double[][] list = new double[n + 1][2];
        Integer[] nodes = new Integer[n + 1];
