import java.util.*;

class DotClusters {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in).useLocale(Locale.US);
        int numberOfPoints = scanner.nextInt();
        double[][] coordMap = new double[numberOfPoints][numberOfPoints];
        double[] minWeights = new double[numberOfPoints];
        int[] closest = new int[numberOfPoints];
        double[][] points = new double[numberOfPoints][2];

        for (int i = 0; i < numberOfPoints; i++) {
            points[i][0] = scanner.nextDouble();
            points[i][1] = scanner.nextDouble();
        }

        for (int i = 0; i < numberOfPoints; i++) {
            for (int j = i; j < numberOfPoints; j++) {
                coordMap[j][i] = coordMap[i][j] = distance(points[i][0], points[j][0], points[i][1], points[j][1]);
            }
        }

        double totalDistance = applyPrim(coordMap, minWeights, closest);
        System.out.printf(Locale.US, "%.2f\n", totalDistance);
    }

    private static double distance(double x1, double x2, double y1, double y2) {
        return Math.sqrt(Math.pow(x1 - x2, 2) + Math.pow(y1 - y2, 2));
    }

    private static double applyPrim(double[][] network, double[] minWeights, int[] closest) {
        double totalDistance = 0;
        Arrays.fill(minWeights, Double.MAX_VALUE);
        int numberOfVertices = minWeights.length;
        boolean[] added = new boolean[numberOfVertices];

        minWeights[0] = 0;
        for (int count = 0; count < numberOfVertices; count++) {
            double min = Double.MAX_VALUE;
            int nextVertex = -1;
            for (int vertexIdx = 0; vertexIdx < numberOfVertices; vertexIdx++) {
                if (!added[vertexIdx] && minWeights[vertexIdx] < min) {
                    nextVertex = vertexIdx;
                    min = minWeights[vertexIdx];
                }
            }

            added[nextVertex] = true;
            for (int vertexIdx = 0; vertexIdx < numberOfVertices; vertexIdx++) {
                if (network[nextVertex][vertexIdx] < minWeights[vertexIdx] && !added[vertexIdx]) {
                    minWeights[vertexIdx] = network[nextVertex][vertexIdx];
                    closest[vertexIdx] = nextVertex;
                }
            }
        }

        for (int vertexIdx = 0; vertexIdx < numberOfVertices; vertexIdx++) {
            totalDistance += minWeights[vertexIdx];
        }

        return totalDistance;
    }
}

