class DynamicStack {
    private int count;
    private StackNode top;

    int getCount() {
        return this.count;
    }
    void push(int value) {
        StackNode newNode = new StackNode(value);
        newNode.setNext(this.top);
        this.top = newNode;
        this.count++;
    }

    int[] extractMembers() {
        int[] elements = new int[this.count];
        StackNode current = this.top;
        int idx = 0;
        while (current != null) {
            elements[idx++] = current.getValue();
            current = current.getNext();
        }
        return elements;
    }
}

