    }
    public static int[][] groupsArray(int[][] array, int i, int j, String a) {
        int empty = array[0].length;
        int m, n, ii, ij, temp, temp1, indexi, indexj, itemp;
        int[] B = { 0 };
        if (a == "the_same") {
            if (empty == 0) {
                array[0] = insertElement(array[0], i, 0);
                array[0] = insertElement(array[0], j, 0);
            } else {
                for (m = 0; m < array.length; m++) {
                    Arrays.sort(array[m]);
                    indexi = arraySearch(array[m], i);
                    indexj = arraySearch(array[m], j);
                    if (indexi >= 0 && indexj >= 0)
                        break;
                    if (indexi < 0 && indexj < 0) {
                        if (array[m].length == 0) {
                            array[m] = insertElement(array[m], i, -(indexi + 1));
                            array[m] = insertElement(array[m], j, -(indexj + 1));
                            break;
                        } else
                            continue;
                    }
                    if (indexi >= 0 && indexj < 0) {
                        temp = m;
                        ij = indexj;
                        temp1 = 0;
                        for (n = m + 1; n < array.length; n++) {
                            Arrays.sort(array[n]);
                            itemp = arraySearch(array[n], j);
                            if (itemp >= 0) {
                                array[temp] = merge(array[temp], array[n]);
                                array[n] = B;
                                temp1 = 1;
                                break;
                            }
                        }
                        if (temp1 == 1)
                            break;
                        else {
                            Arrays.sort(array[temp]);
                            array[temp] = insertElement(array[temp], j, -(ij + 1));
                            break;
                        }
                    }
                    if (indexi < 0 && indexj >= 0) {
                        temp = m;
                        ii = indexi;
                        temp1 = 0;
                        for (n = m + 1; n < array.length; n++) {
                            Arrays.sort(array[n]);
                            indexi = arraySearch(array[n], i);
                            if (indexi >= 0) {
                                array[temp] = merge(array[temp], array[n]);
                                array[n] = B;
                                temp1 = 1;
                                break;
                            }
                        }
                        if (temp1 == 1)
                            break;
                        else {
                            array[temp] = insertElement(array[temp], i, -(ii + 1));
                            break;
                        }
                    }
                }
            }
        } else {
            if (empty == 0) {
                array[0] = insertElement(array[0], i, 0);
                array[1] = insertElement(array[1], j, 0);
            } else {
                for (m = 0; m < array.length; m++) {
                    Arrays.sort(array[m]);
                    indexi = arraySearch(array[m], i);
                    indexj = arraySearch(array[m], j);
                    if (indexi >= 0 && indexj >= 0)
                        break;
                    if (indexi < 0 && indexj < 0) {
                        if (array[m].length == 0 && array[m + 1].length == 0) {
                            array[m] = insertElement(array[m], i, -(indexi + 1));
                            array[m + 1] = insertElement(array[m + 1], j, -(indexj + 1));
                            break;
                        } else
                            continue;
                    }
                    if (indexi >= 0 && indexj < 0) {
                        ij = 0;
                        temp1 = -1;
                        for (n = m + 1; n < array.length; n++) {
                            if (array[n].length == 0 && temp1 == -1)
                                temp1 = n;
                            Arrays.sort(array[n]);
                            itemp = arraySearch(array[n], j);
                            if (itemp >= 0)
                                ij = 1;
                        }
                        if (ij == 1)
                            break;
                        else {
                            Arrays.sort(array[temp1]);
                            array[temp1] = insertElement(array[temp1], j, 0);
                            break;
                        }
                    }
                    if (indexi < 0 && indexj >= 0) {
                        ij = 0;
                        temp1 = -1;
                        for (n = m + 1; n < array.length; n++) {
                            if (array[n].length == 0 && temp1 == -1)
                                temp1 = n;
                            Arrays.sort(array[n]);
                            itemp = arraySearch(array[n], i);
                            if (itemp >= 0)
                                ij = 1;
                        }
                        if (ij == 1)
                            break;
                        else {
                            Arrays.sort(array[temp1]);
                            array[temp1] = insertElement(array[temp1], i, 0);
                            break;
                        }
                    }
                }
            }
        }
        return array;
    }
    private static int[] insertElement(int[] original, int element, int index) {
        int length = original.length;
        int[] destination = new int[length + 1];
        System.arraycopy(original, 0, destination, 0, index);
        destination[index] = element;
        System.arraycopy(original, index, destination, index + 1, length - index);
        return destination;
    }
    public static int[] merge(int[] array1, int[] array2) {
        int[] C = new int[array1.length + array2.length];
        System.arraycopy(array1, 0, C, 0, array1.length);
        System.arraycopy(array2, 0, C, array1.length, array2.length);
        return C;
    }
    public static int arraySearch(int[] array, int val) {
        int index = Arrays.binarySearch(array, val);
        return index;
    }
    public static int[][] Floyd(int[][] nData) {
        int i, j, k;
        int n = nData.length;
        for (k = 0; k < n; k++)
            for (i = 0; i < n; i++)
                for (j = 0; j < n; j++) {
                    if ((nData[i][k] == 1) && (nData[k][j] == 1)) {
                        nData[i][j] = 1;
                    }
                }
        return nData;
    }
    public static void printresult(int[][] nData) {
        int i, j, t1, t2;
        int group = 0;
        int out = 0;
        for (i = 0; i < nData.length; i++) {
            t1 = 0;
            t2 = 0;
            if (nData[i].length >= 4) {
                group++;
            } else {
                if ((nData[i].length == 1) || (nData[i].length == 0)) {
                    for (j = 0; j < nData[i].length; j++) {
                        if (nData[i][j] != 0)
                            t1++;
                    }
                } else {
                    t2 = nData[i].length;
                }
            }
            out = out + t1 + t2;
        }
        System.out.println(group + " " + out);
    }
}

import java.util.Scanner;
import java.util.Arrays;
public class prob21 {
    static double INF = 99999999.0;
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        double[][] p = new double[101][101];
        double[] ax = new double[101];
        double[] ay = new double[101];
        double[] dis = new double[101];
        boolean[] used = new boolean[101];
        int n, i, j;
        n = in.nextInt();
        for (i = 0; i < n; i++) {
            ax[i] = in.nextDouble();
            ay[i] = in.nextDouble();
        }
        for (i = 0; i < n; i++)
            for (j = 0; j < n; j++)
                p[i][j] = INF;
        for (i = 0; i < n; i++)
            for (j = i + 1; j < n; j++) {
                double v = (ax[i] - ax[j]) * (ax[i] - ax[j]) + (ay[i] - ay[j]) * (ay[i] - ay[j]);
                v = Math.sqrt(v);
                if (v < p[i][j])
                    p[i][j] = p[j][i] = v;
            }
        for (i = 0; i < n; i++)
            dis[i] = p[0][i];
        Arrays.fill(used, false);
        dis[0] = 0;
        used[0] = true;
        double ans = 0;
        for (i = 0; i < n - 1; i++) {
            double min = INF;
            int tag = -1;
            for (j = 1; j < n; j++) {
                if (!used[j] && dis[j] < min) {
                    min = dis[j];
                    tag = j;
                }
            }
            used[tag] = true;
            ans += min;
            for (j = 1; j < n; j++) {
                if (!used[j] && dis[j] > p[tag][j])
                    dis[j] = p[tag][j];
            }
        }
        System.out.printf("%.2f\n", ans);
    }
}

import java.util.*;
import java.io.*;

class Vertex {
    boolean isVisited;
    double posX, posY;
    List<Connection> connections;

    Vertex(double posX, double posY) {
        this.isVisited = false;
        this.posX = posX;
        this.posY = posY;
        connections = new LinkedList<>();
    }

    void connect(Connection conn) {
        connections.add(conn);
    }
}

class Network {
    List<Vertex> vertices;
    double totalInk;

    Network() {
        vertices = new LinkedList<>();
        totalInk = 0.0;
    }

    void insert(Vertex vertex) {
        vertices.add(vertex);
    }

    void initializeConnections() {
        LinkedList<Vertex> queue = new LinkedList<>(vertices);
        while (!queue.isEmpty()) {
            Vertex current = queue.pop();
            queue.forEach(vertex -> {
                current.connect(new Connection(current, vertex));
                vertex.connect(new Connection(vertex, current));
            });
        }
    }

    Connection createConnection(Vertex start, Vertex end) {
        return new Connection(start, end);
    }

    double computeMinimumSpanningTree() {
        PriorityQueue<Connection> availableEdges = new PriorityQueue<>(Comparator.comparingDouble(conn -> conn.distance));
        Set<Vertex> unvisited = new HashSet<>(vertices);
        Vertex current = vertices.get(0);
        unvisited.remove(current);

        while (!unvisited.isEmpty()) {
            current.isVisited = true;
            availableEdges.addAll(current.connections);

            Connection shortest;
            while ((shortest = availableEdges.poll()) != null) {
                if (!shortest.end.isVisited) {
                    totalInk += shortest.distance;
                    current = shortest.end;
                    unvisited.remove(current);
                    break;
                }
            }
        }
        return totalInk;
    }
}

class Connection {
    double distance;
    Vertex end;
    Vertex start;

    Connection(Vertex start, Vertex end) {
        this.start = start;
        this.end = end;
        distance = Math.hypot(start.posX - end.posX, start.posY - end.posY);
    }
}

class GraphGenerator {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        Network network = new Network();
        int vertexCount = scanner.nextInt();

        while (vertexCount-- > 0) {
            double posX = scanner.nextDouble();
            double posY = scanner.nextDouble();
            network.insert(new Vertex(posX, posY));
        }

        network.initializeConnections();
        double requiredInk = network.computeMinimumSpanningTree();
        System.out.printf("%.2f\n", requiredInk);
    }
}

