import java.util.*;
class No {
    int aluno;
    Boolean visitado;
    LinkedList<Integer> amigos;
    LinkedList<Integer> DFSresultado;
    No(int alu) {
        aluno = alu;
        amigos = new LinkedList<Integer>();
        DFSresultado = new LinkedList<Integer>();
        visitado = false;
    }
}
class Grafo {
    LinkedList<No> total;
    Grafo() {
        total = new LinkedList<No>();
    }
    void ColocaGrafo(int alu) {
        total.add(new No(alu));
    }
    void AdicionaLigacao(int amigo, int aluno) {
        for (No n : total) {
            if (n.aluno == aluno)
                n.amigos.add(amigo);
        }
    }
    void DFS(Grafo grafo) {
        for (No n : total) {
            if (n.visitado == false)
                DFSVisit(n, grafo, n);
            for (No k : total)
                k.visitado = false;
        }
    }
    void DFSVisit(No z, Grafo grafo, No n) {
        n.visitado = true;
        for (int a : n.amigos)
            for (No f : total) {
                if (a == f.aluno)
                    if (f.visitado == false)
                        DFSVisit(z, grafo, f);
            }
        z.DFSresultado.add(n.aluno);
    }
}
public class Sociologia {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int count = 1;
        int ncenarios = in.nextInt();
        LinkedList<Integer> fim = new LinkedList<Integer>();
        while (count <= ncenarios) {
            int ngrupos = 0, nsgrupo = 0;
            int nalunos = in.nextInt();
            Grafo grafo = new Grafo();
            Grafo grafoT = new Grafo();
            for (int i = 1; i <= nalunos; i++) {
                grafo.ColocaGrafo(i);
                grafoT.ColocaGrafo(i);
            }
            for (int i = 0; i < nalunos; i++) {
                int aluno = in.nextInt();
                int namigos = in.nextInt();
                for (int j = 0; j < namigos; j++) {
                    int amigo = in.nextInt();
                    grafo.AdicionaLigacao(amigo, aluno);
                    grafoT.AdicionaLigacao(aluno, amigo);
                }
            }
            grafo.DFS(grafo);
            grafoT.DFS(grafoT);
            for (No n : grafo.total) {
                if (n.visitado == false) {
                    fim = n.DFSresultado;
                    for (No t : grafoT.total)
                        if (t.aluno == n.aluno)
                            fim.retainAll(t.DFSresultado);
                    for (int h : fim) {
                        for (No f : grafo.total) {
                            if (h == f.aluno && f.DFSresultado.size() != 1)
                                f.visitado = true;
                        }
                    }
                    if (fim.size() >= 4)
                        ngrupos++;
                }
            }
            for (No n : grafo.total)
                if (n.visitado == false)
                    nsgrupo++;
            if (ngrupos == 0)
                nsgrupo = nalunos;
            System.out.println("Caso #" + count);
            System.out.println(ngrupos + " " + nsgrupo);
            count++;
        }
    }
}

import java.util.*;
class Parte3_2 {
    static PriorityQueue<Node> list = new PriorityQueue<Node>();
    static LinkedList<Node> aux = new LinkedList<Node>();
    static float dist = 0;
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        input.useLocale(Locale.US);
        int n = input.nextInt();
        for (int i = 0; i < n; i++) {
            Node node = new Node(input.nextFloat(), input.nextFloat());
            list.add(node);
            aux.add(node);
        }
        prim();
        System.out.format(Locale.ENGLISH, "%.2f", dist);
        System.out.println();
    }
    public static void prim() {
        boolean first = true;
        Node node = null;
        while (list.size() > 0) {
            node = list.remove();
            aux.remove(node);
            if (!first)
                dist += node.dist;
            else
                first = false;
            for (Node adjNode : aux) {
                float weight = returnWeight(node, adjNode);
                if (weight < adjNode.dist) {
                    list.remove(adjNode);
                    adjNode.parent = node;
                    adjNode.dist = weight;
                    list.add(adjNode);
                }
            }
        }
    }
    public static float returnWeight(Node node1, Node node2) {
        return (float) Math.sqrt((node1.x - node2.x) * (node1.x - node2.x) + (node1.y - node2.y) * (node1.y - node2.y));
    }
}
class Node implements Comparable<Node> {
    float dist = Float.MAX_VALUE;
    Node parent = null;
    public float x;
    public float y;
    Node(float x, float y) {
        this.x = x;
        this.y = y;
    }
    public int compareTo(Node n) {
        if (dist < n.dist)
            return -1;
        else if (dist > n.dist)
            return 1;
        else
            return 0;
    }
}

