import java.util.*;
import java.io.*;

class Node {
    boolean visited = false;
    double xCoordinate;
    double yCoordinate;
    List<Edge> adjacentEdges = new LinkedList<>();

    Node(double x, double y) {
        this.xCoordinate = x;
        this.yCoordinate = y;
    }

    void addNeighbor(Edge edge) {
        adjacentEdges.add(edge);
    }
}

class Graph {
    List<Node> vertices = new LinkedList<>();
    double totalInk = 0.0;

    void addVertex(Node node) {
        vertices.add(node);
    }

    void initializeEdges() {
        List<Node> temporaryNodes = new LinkedList<>(vertices);
        while (!temporaryNodes.isEmpty()) {
            Node currentNode = temporaryNodes.remove(0);
            temporaryNodes.forEach(node -> {
                currentNode.addNeighbor(createEdge(currentNode, node));
                node.addNeighbor(createEdge(node, currentNode));
            });
        }
    }

    private Edge createEdge(Node from, Node to) {
        return new Edge(from, to);
    }

    double calculateMinimumSpanningTree() {
        if (vertices.isEmpty()) return 0.0;

        PriorityQueue<Edge> edgePriorityQueue = new PriorityQueue<>(Comparator.comparingDouble(edge -> edge.distance));
        Set<Node> unvisited = new HashSet<>(vertices);
        Node startNode = unvisited.iterator().next();

        visit(startNode, edgePriorityQueue, unvisited);

        while (!edgePriorityQueue.isEmpty() && !unvisited.isEmpty()) {
            Edge shortestEdge = edgePriorityQueue.poll();
            if (unvisited.contains(shortestEdge.to)) {
                totalInk += shortestEdge.distance;
                visit(shortestEdge.to, edgePriorityQueue, unvisited);
            }
        }
        return totalInk;
    }

    private void visit(Node node, PriorityQueue<Edge> edgePriorityQueue, Set<Node> unvisited) {
        node.visited = true;
        unvisited.remove(node);
        node.adjacentEdges.stream()
                .filter(edge -> !edge.to.visited)
                .forEach(edgePriorityQueue::offer);
    }
}

class Edge {
    double distance;
    Node to;
    Node from;

    Edge(Node from, Node to) {
        this.from = from;
        this.to = to;
        this.distance = Math.hypot(from.xCoordinate - to.xCoordinate, from.yCoordinate - to.yCoordinate);
    }
}

