import java.util.*;

class SkinArt {
    private static int depth = 0;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int count = scanner.nextInt();
        Dot[] blueprint = new Dot[count];
        for (int i = 0; i < count; i++) {
            blueprint[i] = new Dot(scanner.nextDouble(), scanner.nextDouble());
        }
        inkDots(blueprint);
    }

    private static void inkDots(Dot[] dots) {
        int clusters = dots.length;
        PriorityQueue<Connection> queue = new PriorityQueue<>();
        for (int current = 0; current < dots.length - 1; current++) {
            for (int next = current + 1; next < dots.length; next++)
                queue.offer(new Connection(current, next, calculateDistance(dots[current], dots[next])));
        }

        double inkTotal = 0;
        while (!queue.isEmpty() && clusters > 1) {
            Connection shortest = queue.poll();
            Dot dotA = dots[shortest.dotA];
            Dot dotB = dots[shortest.dotB];
            depth = 0;
            Dot rootA = dotA.findRoot();
            int depthA = depth;
            depth = 0;
            Dot rootB = dotB.findRoot();
            int depthB = depth;
            if (rootA != rootB) {
                if (depthA > depthB)
                    rootA.mergeRoot(rootB);
                else
                    rootB.mergeRoot(rootA);
                clusters--;
                inkTotal += shortest.distance;
            }
        }
        System.out.printf("%.2f\n", inkTotal);
    }

    private static double calculateDistance(Dot a, Dot b) {
        double deltaX = Math.abs(a.x - b.x);
        double deltaY = Math.abs(a.y - b.y);
        return Math.sqrt((deltaX * deltaX) + (deltaY * deltaY));
    }

    static class Dot {
        Dot ancestor;
        double x, y;

        Dot(double posX, double posY) {
            ancestor = this;
            x = posX;
            y = posY;
        }

        public Dot findRoot() {
            if (ancestor != this) {
                depth++;
                ancestor = ancestor.findRoot();
            }
            return ancestor;
        }

        public void mergeRoot(Dot other) {
            other.ancestor = this;
        }
    }

    static class Connection implements Comparable<Connection> {
        int dotA, dotB;
        double distance;

        Connection(int firstDot, int secondDot, double length) {
            dotA = firstDot;
            dotB = secondDot;
            distance = length;
        }

        @Override
        public int compareTo(Connection other) {
            return Double.compare(this.distance, other.distance);
        }

        @Override
        public String toString() {
            return String.format("(%d,%d,%.2f)", dotA, dotB, distance);
        }
    }
}

