import java.util.*;
class EmptyQueueException extends RuntimeException {
    public EmptyQueueException(String err) {
        super(err);
    }
}
class Node<E> {
    E val;
    Node<E> next;
    Node(E v, Node<E> n) {
        val = v;
        next = n;
    }
}
class Queue<E> {
    private int size;
    private Node<E> first;
    private Node<E> last;
    Queue() {
        size = 0;
        first = last = null;
    }
    public boolean isEmpty() {
        return (size == 0);
    }
    public int size() {
        return size;
    }
    public E dequeue() throws EmptyQueueException {
        if (isEmpty())
            return null;
        E res = first.val;
        first = first.next;
        size--;
        if (first == null)
            last = null;
        return res;
    }
    public void enqueue(E v) {
        Node<E> novo = new Node<E>(v, null);
        if (isEmpty())
            first = last = novo;
        else {
            last.next = null;
            last.next = novo;
            last = novo;
        }
        size++;
    }
}
