                    pais[a] = h;
                    dfs_visitl(o, color, pais, a, p);
                }
            }
        }
        color[h] = "black";
    }
    void dfsl(int[][] oo, int p, int[] f) {
        String[] color = new String[p];
        int[] pais = new int[p];
        for (int i = 0; i < p; i++) {
            color[i] = "white";
        }
        for (int i = 0; i < p; i++) {
            pais[i] = 0;
        }
        Queue<Integer> filas = new Queue<Integer>();
        int u = -1;
        int z = 1;
        int uz = 1;
        while (uz != 0) {
            z = max(p, f);
            if (u != z) {
                filas.enqueue(z);
                f[z] = 0;
                u = z;
            } else {
                uz = 0;
            }
        }
        int cntg = 0;
        int cntf = 0;
        while (!filas.isEmpty()) {
            int q = filas.dequeue();
            if (color[q] == "white") {
                dfs_visitl(oo, color, pais, q, p);
                if (cnt > 3) {
                    cntg++;
                } else {
                    cntf += cnt;
                }
                cnt = 0;
            }
        }
        System.out.println(cntg + " " + cntf);
    }
    int max(int p, int[] f) {
        int max = 0;
        int ind = 0;
        for (int b = 0; b < p; b++) {
            if (max < f[b]) {
                max = f[b];
                ind = b;
            }
        }
        return ind;
    }
    int[] dfs(int[][] o, int p) {
        String[] color = new String[p];
        int[] pais = new int[p];
        int[] d = new int[p];
        int[] f = new int[p];
        for (int i = 0; i < p; i++) {
            color[i] = "white";
        }
        for (int i = 0; i < p; i++) {
            pais[i] = 0;
            f[i] = 0;
            d[i] = 0;
        }
        for (int h = 0; h < p; h++) {
            if (color[h] == "white") {
                dfs_visit(o, color, pais, h, d, p, f);
            }
        }
        return f;
    }
    void dfs_visit(int[][] o, String[] color, int[] pais, int h, int[] d, int p, int[] f) {
        time++;
        d[h] = time;
        color[h] = "gray";
        for (int a = 0; a < p; a++) {
            if (o[h][a] == 1) {
                if (color[a] == "white") {
                    pais[a] = h;
                    dfs_visit(o, color, pais, a, d, p, f);
                }
            }
        }
        color[h] = "black";
        time++;
        f[h] = time;
    }
    int[][] gl(int[][] matriz, int r) {
        int[][] matrizl = new int[r][r];
        for (int ii = 0; ii < r; ii++) {
            for (int jj = 0; jj < r; jj++) {
                if (matriz[ii][jj] == 1) {
                    matrizl[jj][ii] = 1;
                }
            }
        }
        return matrizl;
    }
}
