import java.util.*;

class Freckles {

    public static void main(String[] args) {
        Scanner stdin = new Scanner(System.in);
        int numberOfPoints = stdin.nextInt();
        Point[] faceMap = new Point[numberOfPoints];
        for (int i = 0; i < numberOfPoints; i++) {
            faceMap[i] = new Point(stdin.nextDouble(), stdin.nextDouble());
        }
        drawOnHisFace(faceMap);
    }

    public static void drawOnHisFace(Point[] face) {
        int groups = face.length;
        PriorityQueue<Link> links = new PriorityQueue<>();
        for (int i = 0; i < face.length - 1; i++) {
            for (int j = i + 1; j < face.length; j++) {
                links.add(new Link(i, j, distance(face[i], face[j])));
            }
        }

        double totalDistance = 0;
        while (!links.isEmpty() && groups > 1) {
            Link closestLink = links.poll();
            if (closestLink.connectsDifferentGroups(face)) {
                --groups;
                totalDistance += closestLink.distance;
            }
        }
        System.out.format("%.2f\n", totalDistance);
    }

    public static double distance(Point a, Point b) {
        double deltaX = Math.abs(a.x - b.x);
        double deltaY = Math.abs(a.y - b.y);
        return Math.sqrt((deltaX * deltaX) + (deltaY * deltaY));
    }
}

class Point {
    Point parent;
    double x, y;

    Point(double x, double y) {
        this.x = x;
        this.y = y;
        this.parent = this;
    }

    public Point findParent() {
        if (parent != this) {
            parent = parent.findParent();
        }
        return parent;
    }

    public void uniteRoots(Point other) {
        other.findParent().parent = this;
    }
}

class Link implements Comparable<Link> {
    int pointIndexA;
    int pointIndexB;
    double distance;

    Link(int pointIndexA, int pointIndexB, double distance) {
        this.pointIndexA = pointIndexA;
        this.pointIndexB = pointIndexB;
        this.distance = distance;
    }

    @Override
    public int compareTo(Link other) {
        return Double.compare(this.distance, other.distance);
    }

    public boolean connectsDifferentGroups(Point[] points) {
        Point rootA = points[pointIndexA].findParent();
        Point rootB = points[pointIndexB].findParent();
        if (rootA != rootB) {
            rootA.uniteRoots(rootB);
            return true;
        }
        return false;
    }
}

