import java.util.*;

class Node {
    public boolean visited = false;
    public final double x;
    public final double y;
    public final List<Edge> adj;

    Node(double x, double y) {
        this.x = x;
        this.y = y;
        adj = new LinkedList<>();
    }

    public void addEdge(Edge edge) {
        adj.add(edge);
    }
}

class Graph {
    public final List<Node> nodes;
    public double ink;

    Graph() {
        nodes = new LinkedList<>();
    }

    public void addNode(Node node) {
        nodes.add(node);
    }

    public void populateGraph() {
        for (Node parent : nodes) {
            for (Node child : nodes) {
                if (parent != child) {
                    Edge edge = new Edge(parent, child);
                    parent.addEdge(edge);
                }
            }
        }
    }

    public double calculateMinimumSpanningTree() {
        PriorityQueue<Edge> edgeQueue = new PriorityQueue<>(Comparator.comparingDouble(e -> e.weight));
        Node startNode = nodes.get(0);
        startNode.visited = true;
        edgeQueue.addAll(startNode.adj);

        while (!edgeQueue.isEmpty()) {
            Edge lowestEdge = edgeQueue.poll();
            Node targetNode = lowestEdge.target;

            if (!targetNode.visited) {
                ink += lowestEdge.weight;
                targetNode.visited = true;

                for (Edge adjoiningEdge : targetNode.adj) {
                    if (!adjoiningEdge.target.visited) {
                        edgeQueue.add(adjoiningEdge);
                    }
                }
            }
        }
        return ink;
    }
}

class Edge {
    public final double weight;
    public final Node target;

    Edge(Node from, Node target) {
        this.target = target;
        weight = Math.sqrt(Math.pow(from.x - target.x, 2) + Math.pow(from.y - target.y, 2));
    }
}

class Sardas {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        Graph graph = new Graph();

        int nodesCount = input.nextInt();
        for (int i = 0; i < nodesCount; i++) {
            double x = input.nextDouble();
            double y = input.nextDouble();
            Node node = new Node(x, y);
            graph.addNode(node);
        }

        graph.populateGraph();
        double minimumInkNeeded = graph.calculateMinimumSpanningTree();
        System.out.printf("%.2f%n", minimumInkNeeded);
    }
}

