import java.util.*;
import java.io.*;
import java.lang.Math;

class Vertex {
    double xCoord;
    double yCoord;
    Vertex parent;
    int id;
    Vertex() {}
    Vertex(double x, double y, int nodeId) {
        id = nodeId;
        xCoord = x;
        yCoord = y;
        parent = null;
    }
}

class Network {
    int size;
    int vertexCount;
    Vertex[] vertexList;
    Network(int s) {
        size = s;
        vertexList = new Vertex[s];
        vertexCount = 0;
        Arrays.fill(vertexList, new Vertex());
    }

    void insertVertex(Vertex v) {
        if (vertexCount < size) {
            vertexList[vertexCount++] = v;
        }
    }
}

class Cluster {
    LinkedList<Vertex> memberVertices;
    int clusterId;
    Cluster(Vertex startVertex, int identity) {
        memberVertices = new LinkedList<>();
        memberVertices.add(startVertex);
        clusterId = identity;
    }
}

class Connection implements Comparable<Connection> {
    Vertex start;
    Vertex end;
    double length;
    Connection(Vertex startPt, Vertex endPt) {
        start = startPt;
        end = endPt;
        length = Math.hypot(endPt.xCoord - startPt.xCoord, endPt.yCoord - startPt.yCoord);
    }

    @Override
    public int compareTo(Connection that) {
        return Double.compare(this.length, that.length);
    }
}

class MinimalSpanningTree {
    static LinkedList<Cluster> clusters;
    static LinkedList<Connection> mstEdges;
    static LinkedList<Connection> allConnections;

    static int locate(Vertex vertex) {
        for (int i = 0; i < clusters.size(); i++) {
            for (Vertex v : clusters.get(i).memberVertices) {
                if (v.xCoord == vertex.xCoord && v.yCoord == vertex.yCoord) {
                    return i;
                }
            }
        }
        return -1;
    }

    static void combine(int idx1, int idx2) {
        clusters.get(idx1).memberVertices.addAll(clusters.get(idx2).memberVertices);
        clusters.remove(idx2);
    }

    static void reIndexClusters() {
        int index = 0;
        for (Cluster cl : clusters) {
            cl.clusterId = index++;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        Network network = new Network(scanner.nextInt());
        for (int i = 0; i < network.size; i++) {
            Vertex v = new Vertex(scanner.nextDouble(), scanner.nextDouble(), i);
            network.insertVertex(v);
        }

        mstEdges = new LinkedList<>();
        allConnections = new LinkedList<>();
        clusters = new LinkedList<>();

        for (int i = 0; i < network.size; i++) {
            clusters.add(new Cluster(network.vertexList[i], i));
        }

        for (int i = 0; i < network.size; i++) {
            for (int j = i + 1; j < network.size; j++) {
                allConnections.add(new Connection(network.vertexList[i], network.vertexList[j]));
            }
        }

        Collections.sort(allConnections);
        allConnections.forEach(conn -> {
            int clusterIdx1 = locate(conn.start);
            int clusterIdx2 = locate(conn.end);
            if (clusterIdx1 != clusterIdx2) {
                mstEdges.add(conn);
                combine(clusterIdx1, clusterIdx2);
            }
        });

        double totalLength = mstEdges.stream().mapToDouble(conn -> conn.length).sum();
        System.out.printf("%.2f\n", totalLength);
    }
}

