class Node implements Comparable<Node> {
    double weight;
    int from;
    int to;

    Node(double weight, int from, int to) {
        this.weight = weight;
        this.from = from;
        this.to = to;
    }

    public int compareTo(Node other) {
        return Double.compare(this.weight, other.weight);
    }
}

class DisjointSet {
    private int[] parent;
    private int[] rank;

    public DisjointSet(int size) {
        parent = new int[size];
        rank = new int[size];
        for (int i = 0; i < size; i++) {
            parent[i] = i;
            rank[i] = 0;
        }
    }

    public int find(int i) {
        if (parent[i] != i) {
            parent[i] = find(parent[i]);
        }
        return parent[i];
    }

    public void union(int i, int j) {
        int rootI = find(i);
        int rootJ = find(j);

        if (rank[rootI] > rank[rootJ]) {
            parent[rootJ] = rootI;
        } else if (rank[rootI] < rank[rootJ]) {
            parent[rootI] = rootJ;
        } else {
            parent[rootJ] = rootI;
            rank[rootI]++;
        }
    }

    public boolean isSameSet(int i, int j) {
        return find(i) == find(j);
    }
}

class Graph {
    private List<Node> edges;
    private int vertexCount;

    public Graph(int vertexCount) {
        this.vertexCount = vertexCount;
        edges = new ArrayList<>();
    }

    public void addEdge(double weight, int from, int to) {
        edges.add(new Node(weight, from, to));
    }

    public double calculateMinimumSpanningTree() {
        double cost = 0;
        DisjointSet disjointSet = new DisjointSet(vertexCount);
        Collections.sort(edges);

        for (Node edge : edges) {
            if (!disjointSet.isSameSet(edge.from, edge.to)) {
                disjointSet.union(edge.from, edge.to);
                cost += edge.weight;
            }
        }
        return cost;
    }
}

class KruskalMSTCalculator {
    public static void main(String[] args) throws IOException {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        double[] xCoordinates = new double[n];
        double[] yCoordinates = new double[n];

        for (int i = 0; i < n; ++i) {
            xCoordinates[i] = scanner.nextDouble();
            yCoordinates[i] = scanner.nextDouble();
        }

        Graph graph = new Graph(n);
        for (int i = 0; i < n - 1; ++i) {
            for (int j = i + 1; j < n; ++j) {
                double distance = calculateDistance(xCoordinates[i], xCoordinates[j], yCoordinates[i], yCoordinates[j]);
                graph.addEdge(distance, i, j);
            }
        }

        System.out.printf("%.2f%n", graph.calculateMinimumSpanningTree());
    }

    private static double calculateDistance(double x1, double x2, double y1, double y2) {
        double dx = x1 - x2;
        double dy = y1 - y2;
        return Math.sqrt(dx * dx + dy * dy);
    }
}

